/* =============================================================================================
   HELPERS
   ============================================================================================= */
const money = new Intl.NumberFormat("pt-BR", { style: "currency", currency: "BRL" });
const number = new Intl.NumberFormat("pt-BR", { maximumFractionDigits: 1 });
const numberInt = new Intl.NumberFormat("pt-BR");

function normalizeHeader(value) {
  return String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function numeric(value) {
  if (value === null || value === undefined || value === "") return 0;
  if (typeof value === "number") return value;
  const text = String(value).trim();
  const normalized = text.includes(",") ? text.replace(/\./g, "").replace(",", ".") : text;
  const parsed = Number(normalized);
  return Number.isFinite(parsed) ? parsed : 0;
}

const excludedVehiclePattern = /CONJUNTO ANTER|CONJUN ESPEC|CONJUN COMPL|CONJUNTO ESPEC|CONJUNTO COMPL|CAV BITREM TRACADO/i;
/* =============================================================================================
   MANIFESTO — vincula coletas ao mesmo veículo/manifesto (NR_MANIFESTOS x NR_DIARIO_BORDO) para
   evitar contar 2x quando um único despacho atende 2 clientes na mesma cidade (ex.: ACHE+LABOFARMA
   num mesmo cavalo mecânico). Nesse caso, mantém só o cliente de maior Valor Médio calibrado.
   ============================================================================================= */
function normalizeManifestNumber(v) {
  const n = Number(v);
  return Number.isFinite(n) && String(v ?? "").trim() !== "" ? String(Math.round(n)) : String(v ?? "").trim();
}
function normalizeVehicleClass(raw) {
  const v = String(raw ?? "").trim().toUpperCase();
  return v.startsWith("CAV") ? "CAV.MECANICO" : ["TRUCK", "TOCO", "TOCO 3/4", "VAN", "FIORINO"].includes(v) ? v : "OUTROS";
}
/* Mapeamento CNPJ -> GRUPO comercial (planilha RESUM. CLIENTE / lista fornecida). Usado para
   colapsar, dentro do mesmo manifesto, pedidos de CNPJs que são a mesma empresa/grupo
   (ex.: ACHE + LABOFARMA), tanto na deduplicação de receita quanto na contagem de veículos. */

