/* rows no formato array-de-arrays (header:1), pois o relatório de manifesto tem linhas de parâmetro antes do cabeçalho real */
function parseManifestReport(rows) {
  if (!rows.length) throw new Error("A planilha de manifesto não possui linhas de dados.");
  let headerRowIndex = -1, headerMap = null;
  for (let i = 0; i < Math.min(rows.length, 30); i++) {
    const normalized = (rows[i] ?? []).map(headerClient);
    const find = (name) => normalized.indexOf(headerClient(name));
    const map = {
      manifesto: find("NR_MANIFESTOS"), placa: find("IDENT_VEICULOS_TRACAO"),
      aproveitamento: find("PC_APROVEITAMENTO"), classe: find("CLASSE_VEICULO_VIAGEM"),
      rota: find("ROTA_VIAGEM"), km: find("KM_TOTAL_VIAGEM"), data: find("DT_VIAGENS"),
      entregas: find("QT_ENTREGAS_VIAGENS"), devolucoes: find("QTD_CTE_NAO_ENTREGUE"),
    };
    if (map.manifesto !== -1 && map.placa !== -1) { headerRowIndex = i; headerMap = map; break; }
  }
  if (headerRowIndex === -1) throw new Error("Não encontrei as colunas NR_MANIFESTOS e IDENT_VEICULOS_TRACAO na planilha de manifesto.");
  const byManifest = new Map();
  const plates = new Set();
  const classeCounter = new Map();
  let aproveitamentoSum = 0, aproveitamentoCount = 0;
  for (const row of rows.slice(headerRowIndex + 1)) {
    const nrRaw = row[headerMap.manifesto];
    if (nrRaw === undefined || nrRaw === null || String(nrRaw).trim() === "") continue;
    const placa = String(row[headerMap.placa] ?? "").trim();
    const aproveitamento = headerMap.aproveitamento !== -1 ? Number(row[headerMap.aproveitamento]) : null;
    const classe = headerMap.classe !== -1 ? String(row[headerMap.classe] ?? "").trim() : "";
    const rota = headerMap.rota !== -1 ? String(row[headerMap.rota] ?? "").trim() : "";
    const km = headerMap.km !== -1 ? Number(row[headerMap.km]) : null;
    const data = headerMap.data !== -1 ? String(row[headerMap.data] ?? "").trim() : "";
    const entregas = headerMap.entregas !== -1 ? Number(row[headerMap.entregas]) || 0 : 0;
    const devolucoes = headerMap.devolucoes !== -1 ? Number(row[headerMap.devolucoes]) || 0 : 0;
    byManifest.set(normalizeManifestNumber(nrRaw), { placa, aproveitamento, classe, rota, km, data, entregas, devolucoes });
    if (placa) plates.add(placa);
    if (classe) classeCounter.set(classe, (classeCounter.get(classe) ?? 0) + 1);
    if (Number.isFinite(aproveitamento)) { aproveitamentoSum += aproveitamento; aproveitamentoCount += 1; }
  }
  if (!byManifest.size) throw new Error("Nenhum manifesto válido encontrado (colunas NR_MANIFESTOS / IDENT_VEICULOS_TRACAO).");
  const classeBreakdown = Array.from(classeCounter.entries()).map(([classe, count]) => ({ classe, count })).sort((a, b) => b.count - a.count);
  return {
    byManifest, totalManifests: byManifest.size, uniquePlates: plates.size,
    avgAproveitamento: aproveitamentoCount > 0 ? aproveitamentoSum / aproveitamentoCount : null,
    classeBreakdown,
  };
}


