function Home() {
  const [vehicle, setVehicle] = useState("Cavalo");
  const [daily, setDaily] = useState(696.06);
  const [helperDaily, setHelperDaily] = useState(0);
  const [freightWeight, setFreightWeight] = useState(0);
  const [currentFranchise, setCurrentFranchise] = useState(150);
  const [projectedFranchise, setProjectedFranchise] = useState(100);
  const [projectedExcessKm, setProjectedExcessKm] = useState(32);
  const [excessRate, setExcessRate] = useState(3.82);
  const [km, setKm] = useState(132);
  const [hours, setHours] = useState(3);
  const [fuelPrice, setFuelPrice] = useState(5.5);
  const [fuelType, setFuelType] = useState("Diesel");
  const [gasolinePrice, setGasolinePrice] = useState(0);
  const [ethanolPrice, setEthanolPrice] = useState(0);
  const [efficiency, setEfficiency] = useState(2.8);
  const [efficiencyWasAdjusted, setEfficiencyWasAdjusted] = useState(false);
  const [fleet, setFleet] = useState(1);
  const [monthlyTrips, setMonthlyTrips] = useState(22);
  const [scenarioName, setScenarioName] = useState("");
  const [savedScenarios, setSavedScenarios] = useState([]);
  const [scenariosLoaded, setScenariosLoaded] = useState(false);
  const [comparisonVehicles, setComparisonVehicles] = useState(vehicleSizeOrder);
  const [comparisonScenarioId, setComparisonScenarioId] = useState("");
  const [comparisonSort, setComparisonSort] = useState("economia");
  const [selectedRuleTable, setSelectedRuleTable] = useState(null);
  const [operationFilter, setOperationFilter] = useState("Todos");
  const [rules, setRules] = useState(freightRules);
  const [sourceMeta, setSourceMeta] = useState({ name: "TABELAGRU21.08.26.xlsx", rowCount: freightRules.length, importedAt: "Base atualizada · 21/08/2026" });
  const [importError, setImportError] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => { storageGet("tragetta-frete-scenarios", []).then((value) => { setSavedScenarios(value); setScenariosLoaded(true); }); }, []);

  const operations = useMemo(() => ["Todos", ...Array.from(new Set(rules.map((rule) => rule.operation)))], [rules]);
  const vehicleOptions = useMemo(() => Array.from(new Set(rules.map((rule) => rule.vehicle))).map((key) => Object.entries(vehicleRuleKey).find(([, value]) => value === key)?.[0] ?? key).filter((label) => vehicleSizeOrder.includes(label)).sort((a, b) => vehicleSizeOrder.indexOf(a) - vehicleSizeOrder.indexOf(b)), [rules]);
  const activeRules = useMemo(() => rules.filter((rule) => rule.vehicle === vehicleRuleKey[vehicle] && (operationFilter === "Todos" || rule.operation === operationFilter)).sort((a, b) => a.table - b.table), [rules, vehicle, operationFilter]);
  const selectedRule = activeRules.find((rule) => rule.table === selectedRuleTable) ?? activeRules[0];

  useEffect(() => {
    if (!selectedRule) return;
    setDaily(selectedRule.maxDaily);
    setCurrentFranchise(selectedRule.exemptKm);
    setExcessRate(Number(selectedRule.kmRate.toFixed(2)));
    setHelperDaily(selectedRule.resource);
    setSelectedRuleTable(selectedRule.table);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedRule?.table, selectedRule?.vehicle, operationFilter, rules]);

  const [clients, setClients] = useState([{ id: 1, name: "Cliente / rota a definir", km: 180, vehicles: 1, monthlyTrips: 22 }]);
  const [monthlyReportMeta, setMonthlyReportMeta] = useState(null);
  const [monthlyImportError, setMonthlyImportError] = useState(null);
  const monthlyFileInputRef = useRef(null);

  const calc = useMemo(() => {
    const fixedDaily = daily + helperDaily + freightWeight;
    const effectiveFuelPrice = vehicle === "Fiorino" ? (fuelType === "Gasolina" ? gasolinePrice : ethanolPrice) : fuelPrice;
    const currentFuelCost = efficiency > 0 ? (km / efficiency) * effectiveFuelPrice : 0;
    const projectedTotalKm = Math.max(0, projectedFranchise + projectedExcessKm);
    const projectedFuelCost = efficiency > 0 ? (projectedTotalKm / efficiency) * effectiveFuelPrice : 0;
    const currentExcessKm = Math.max(0, km - currentFranchise);
    const currentExcess = currentExcessKm * excessRate;
    const projectedExcess = Math.max(0, projectedExcessKm) * excessRate;
    const currentPerVehicle = fixedDaily + currentExcess;
    const projectedPerVehicle = fixedDaily + projectedExcess;
    const totalVehicles = clients.reduce((sum, client) => sum + Math.max(0, client.vehicles), 0) || fleet;
    const trips = Math.max(0, monthlyTrips);
    const monthlyDailyCost = projectedPerVehicle * totalVehicles * trips;
    const monthlyFuelCost = projectedFuelCost * totalVehicles * trips;
    const monthlyClientsServed = clients.length * trips;
    const monthlyVehicleServices = totalVehicles * trips;
    const monthlyTotalCost = monthlyDailyCost + monthlyFuelCost;
    return { fixedDaily, currentFuelCost, projectedFuelCost, projectedTotalKm, currentExcessKm, currentExcess, projectedExcess, currentPerVehicle, projectedPerVehicle, savings: currentPerVehicle - projectedPerVehicle, totalVehicles, projectedTotal: projectedPerVehicle * totalVehicles, currentTotal: currentPerVehicle * totalVehicles, monthlyTrips: trips, monthlyDailyCost, monthlyFuelCost, monthlyClientsServed, monthlyVehicleServices, monthlyTotalCost };
  }, [daily, helperDaily, freightWeight, currentFranchise, projectedFranchise, projectedExcessKm, excessRate, km, fuelPrice, fuelType, gasolinePrice, ethanolPrice, efficiency, vehicle, fleet, clients, monthlyTrips]);

  async function handleExcelImport(event) {
    const file = event.target.files?.[0];
    if (!file) return;
    setImportError(null);
    try {
      const buffer = await file.arrayBuffer();
      const workbook = XLSX.read(buffer, { type: "array" });
      const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(firstSheet, { defval: "" });
      const imported = parseImportedRules(rows);
      if (!imported.length) throw new Error("Nenhuma regra válida foi encontrada.");
      setRules(imported);
      setOperationFilter("Todos");
      setSelectedRuleTable(imported[0].table);
      setSourceMeta({ name: file.name, rowCount: imported.length, importedAt: new Date().toLocaleString("pt-BR") });
    } catch (error) {
      setImportError(error instanceof Error ? error.message : "Não foi possível ler a planilha.");
    } finally {
      event.target.value = "";
    }
  }

  function loadRule(rule) {
    setSelectedRuleTable(rule.table);
    setDaily(rule.maxDaily);
    setCurrentFranchise(rule.exemptKm);
    setExcessRate(Number(rule.kmRate.toFixed(2)));
    setHelperDaily(rule.resource);
    setFreightWeight(0);
    setEfficiency(dieselEfficiencyByVehicle[rule.vehicle] ?? efficiency);
  }

  const consolidatedRows = useMemo(() => rules.filter((rule) => operationFilter === "Todos" || rule.operation === operationFilter).map((rule) => {
    const excessKm = Math.max(0, km - rule.exemptKm);
    const fuel = efficiency > 0 ? (km / efficiency) * fuelPrice : 0;
    return { rule, excessKm, fuelCost: fuel, simulatedCost: rule.maxDaily + excessKm * rule.kmRate, excessDailyValue: rule.maxDaily * rule.excessDaily };
  }).sort((a, b) => (vehicleSortOrder.indexOf(a.rule.vehicle) - vehicleSortOrder.indexOf(b.rule.vehicle)) || a.rule.operation.localeCompare(b.rule.operation) || a.rule.table - b.rule.table), [rules, km, efficiency, fuelPrice, operationFilter]);

  const chartRows = useMemo(() => { const grouped = new Map(); consolidatedRows.forEach(({ rule, simulatedCost }) => { const label = Object.entries(vehicleRuleKey).find(([, value]) => value === rule.vehicle)?.[0] ?? rule.vehicle; const total = simulatedCost * calc.totalVehicles; grouped.set(label, Math.min(grouped.get(label) ?? Number.POSITIVE_INFINITY, total)); }); return Array.from(grouped.entries()).map(([label, total]) => ({ label, total })).sort((a, b) => vehicleSizeOrder.indexOf(a.label) - vehicleSizeOrder.indexOf(b.label)); }, [consolidatedRows, calc.totalVehicles]);
  const chartMax = Math.max(...chartRows.map((row) => row.total), 1);
  const comparisonScenario = savedScenarios.find((scenario) => scenario.id === comparisonScenarioId);
  const multiVehicleComparison = useMemo(() => comparisonVehicles.map((label) => { const rule = rules.find((item) => item.vehicle === vehicleRuleKey[label] && (comparisonScenario?.operationFilter === undefined || comparisonScenario.operationFilter === "Todos" || item.operation === comparisonScenario.operationFilter)); const base = comparisonScenario ?? { daily, helperDaily, freightWeight, currentFranchise, projectedFranchise, projectedExcessKm, excessRate, km }; if (!rule) return { label, current: 0, projected: 0, difference: 0, percent: 0, saving: 0, savingPercent: 0 }; const current = rule.maxDaily + Math.max(0, base.km - rule.exemptKm) * rule.kmRate; const projected = rule.maxDaily + Math.max(0, base.projectedExcessKm) * rule.kmRate; const difference = projected - current; const saving = current - projected; return { label, current, projected, difference, percent: current > 0 ? (difference / current) * 100 : 0, saving, savingPercent: current > 0 ? (saving / current) * 100 : 0 }; }), [comparisonVehicles, rules, comparisonScenario, daily, helperDaily, freightWeight, currentFranchise, projectedFranchise, projectedExcessKm, excessRate, km]);
  const multiChartMax = Math.max(...multiVehicleComparison.flatMap((row) => [row.current, row.projected]), 1);
  const sortedMultiVehicleComparison = useMemo(() => [...multiVehicleComparison].sort((a, b) => comparisonSort === "economia" ? b.saving - a.saving : b.percent - a.percent), [multiVehicleComparison, comparisonSort]);

  function saveScenario() {
    const name = scenarioName.trim() || `Cenário ${savedScenarios.length + 1}`;
    const scenario = { id: `${Date.now()}`, name, savedAt: new Date().toLocaleString("pt-BR"), vehicle, daily, helperDaily, freightWeight, currentFranchise, projectedFranchise, projectedExcessKm, excessRate, km, hours, fuelPrice, fuelType, gasolinePrice, ethanolPrice, efficiency, fleet, monthlyTrips, selectedRuleTable, operationFilter, clients };
    const next = [scenario, ...savedScenarios].slice(0, 12);
    setSavedScenarios(next);
    storageSet("tragetta-frete-scenarios", next);
    setScenarioName("");
  }
  function loadScenario(scenario) {
    setVehicle(scenario.vehicle); setDaily(scenario.daily); setHelperDaily(scenario.helperDaily); setFreightWeight(scenario.freightWeight); setCurrentFranchise(scenario.currentFranchise); setProjectedFranchise(scenario.projectedFranchise); setProjectedExcessKm(scenario.projectedExcessKm); setExcessRate(scenario.excessRate); setKm(scenario.km); setHours(scenario.hours); setFuelPrice(scenario.fuelPrice); setFuelType(scenario.fuelType); setGasolinePrice(scenario.gasolinePrice); setEthanolPrice(scenario.ethanolPrice); setEfficiency(scenario.efficiency); setEfficiencyWasAdjusted(Math.abs(scenario.efficiency - (dieselEfficiencyByVehicle[vehicleRuleKey[scenario.vehicle]] ?? scenario.efficiency)) > 0.001); setFleet(scenario.fleet); setMonthlyTrips(scenario.monthlyTrips ?? 22); setSelectedRuleTable(scenario.selectedRuleTable); setOperationFilter(scenario.operationFilter); setClients(scenario.clients);
  }
  function exportPdf() { window.print(); }

  function updateClient(id, key, value) {
    setClients((items) => items.map((item) => item.id === id ? { ...item, [key]: key === "name" ? value : Number(value) } : item));
  }
  function addClient() { setClients((items) => [...items, { id: Date.now(), name: "Novo cliente", km, vehicles: 1, monthlyTrips }]); }
  function removeClient(id) { setClients((items) => items.length > 1 ? items.filter((item) => item.id !== id) : items); }

  const clientMonthlyRows = useMemo(() => clients.map((client) => {
    const perTripFreight = (daily + helperDaily + freightWeight + Math.max(0, client.km - projectedFranchise) * excessRate) * Math.max(0, client.vehicles);
    const perTripFuel = efficiency > 0 ? (client.km / efficiency) * fuelPrice * Math.max(0, client.vehicles) : 0;
    const trips = Math.max(0, client.monthlyTrips ?? 0);
    return { ...client, perTripFreight, perTripFuel, perTripTotal: perTripFreight + perTripFuel, monthlyFreight: perTripFreight * trips, monthlyFuel: perTripFuel * trips, monthlyTotal: (perTripFreight + perTripFuel) * trips };
  }), [clients, daily, helperDaily, freightWeight, projectedFranchise, excessRate, efficiency, fuelPrice]);

  const clientMonthlyTotals = useMemo(() => clientMonthlyRows.reduce((acc, row) => ({ freight: acc.freight + row.monthlyFreight, fuel: acc.fuel + row.monthlyFuel, total: acc.total + row.monthlyTotal, trips: acc.trips + Math.max(0, row.monthlyTrips ?? 0) }), { freight: 0, fuel: 0, total: 0, trips: 0 }), [clientMonthlyRows]);

  async function handleMonthlyReportImport(event) {
    const file = event.target.files?.[0];
    if (!file) return;
    setMonthlyImportError(null);
    try {
      const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" });
      const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" });
      const parsed = parseMonthlyCollectionsReport(rows);
      if (!parsed.length) throw new Error("Nenhum cliente foi identificado na planilha.");
      setClients((current) => {
        const merged = current.map((item) => ({ ...item }));
        let nextId = merged.reduce((max, item) => Math.max(max, item.id), 0) + 1;
        parsed.forEach((item) => {
          const idx = merged.findIndex((existing) => normalizeName(existing.name) === normalizeName(item.name));
          if (idx >= 0) merged[idx] = { ...merged[idx], monthlyTrips: item.trips, km: item.km ?? merged[idx].km };
          else merged.push({ id: nextId++, name: item.name, km: item.km ?? km, vehicles: 1, monthlyTrips: item.trips });
        });
        return merged;
      });
      setMonthlyReportMeta({ name: file.name, clientCount: parsed.length, rowCount: rows.length, importedAt: new Date().toLocaleString("pt-BR") });
    } catch (error) {
      setMonthlyImportError(error instanceof Error ? error.message : "Não foi possível ler o relatório de coletas.");
    } finally {
      event.target.value = "";
    }
  }

  return (
    <main className="workspace">
      <aside className="control-panel">
        <div className="panel-intro"><span className="section-kicker">01 / PREMISSAS</span><h2>Simulador Frete Excedente</h2><p>Altere os parâmetros e acompanhe a projeção de custo em tempo real.</p></div>
        <div className="form-section"><div className="section-heading"><Truck size={17} /><span>Veículo e diária</span></div>
          <Field label="Tipo de veículo"><div className="segmented">{vehicleOptions.map((item) => <button key={item} type="button" className={vehicle === item ? "active" : ""} onClick={() => { const vehicleRule = rules.find((rule) => rule.vehicle === vehicleRuleKey[item] && (operationFilter === "Todos" || rule.operation === operationFilter)); setVehicle(item); if (vehicleRule) { setDaily(vehicleRule.maxDaily); setCurrentFranchise(vehicleRule.exemptKm); setProjectedFranchise(vehicleRule.exemptKm); setExcessRate(vehicleRule.kmRate); setHelperDaily(vehicleRule.resource); setSelectedRuleTable(vehicleRule.table); } setEfficiency(dieselEfficiencyByVehicle[vehicleRuleKey[item]] ?? efficiency); setEfficiencyWasAdjusted(false); setFuelType(item === "Fiorino" ? "Gasolina" : "Diesel"); }}>{item}</button>)}</div></Field>
          <div className="form-grid"><Field label="Diária fixa" hint="R$ / dia"><div className="input-prefix"><span>R$</span><input type="number" min="0" step="0.01" value={daily} onChange={(e) => setDaily(Number(e.target.value))} /></div></Field><Field label="Veículos / dia"><input type="number" min="1" value={fleet} onChange={(e) => setFleet(Number(e.target.value))} /></Field></div>
          <div className="form-grid"><Field label="Ajudante genérico" hint="R$ / dia"><div className="input-prefix"><span>R$</span><input type="number" min="0" step="0.01" value={helperDaily} onChange={(e) => setHelperDaily(Number(e.target.value))} /></div></Field><Field label="Frete peso" hint="R$ / dia"><div className="input-prefix"><span>R$</span><input type="number" min="0" step="0.01" value={freightWeight} onChange={(e) => setFreightWeight(Number(e.target.value))} /></div></Field></div>
        </div>
        <div className="form-section"><div className="section-heading"><SlidersHorizontal size={17} /><span>Franquia e excedente</span></div>
          <div className="form-grid"><Field label="Regra atual" hint="km vigentes na tabela"><input type="number" min="0" value={currentFranchise} onChange={(e) => setCurrentFranchise(Number(e.target.value))} /></Field><Field label="Nova regra" hint="km vigentes na tabela"><input className="input-highlight" type="number" min="0" value={projectedFranchise} onChange={(e) => setProjectedFranchise(Number(e.target.value))} /></Field></div>
          <Field label="KM excedente — nova regra" hint="km cobrados acima da franquia"><input className="input-highlight" type="number" min="0" value={projectedExcessKm} onChange={(e) => setProjectedExcessKm(Number(e.target.value))} /></Field>
          <Field label="Km excedente" hint="R$ / km"><div className="input-prefix"><span>R$</span><input type="number" min="0" step="0.01" value={excessRate} onChange={(e) => setExcessRate(Number(e.target.value))} /></div></Field>
          <div className="km-ruler"><div><span>Regra atual</span><strong>{currentFranchise} km</strong></div><div className="ruler-line"><i style={{ width: `${Math.min(100, (projectedFranchise / Math.max(currentFranchise, calc.projectedTotalKm)) * 100)}%` }} /></div><div><span>Nova regra total</span><strong className="amber-text">{calc.projectedTotalKm} km</strong></div></div>
        </div>
        <div className="form-section"><div className="section-heading"><Fuel size={17} /><span>Consumo Diesel</span></div>
          <div className="form-grid"><Field label="KM total nova rota" hint="km totais do cliente"><input type="number" min="0" value={km} onChange={(e) => setKm(Number(e.target.value))} /></Field><Field label="Deslocamento" hint="horas"><input type="number" min="0" step="0.5" value={hours} onChange={(e) => setHours(Number(e.target.value))} /></Field></div>
          {vehicle === "Fiorino" ? <div className="form-grid"><Field label="Combustível" hint="preço por litro"><select value={fuelType} onChange={(e) => setFuelType(e.target.value)}><option value="Gasolina">Gasolina</option><option value="Álcool">Álcool</option></select></Field><Field label={fuelType} hint="R$ / litro · informar depois"><div className="input-prefix"><span>R$</span><input type="number" min="0" step="0.01" value={fuelType === "Gasolina" ? gasolinePrice : ethanolPrice} onChange={(e) => fuelType === "Gasolina" ? setGasolinePrice(Number(e.target.value)) : setEthanolPrice(Number(e.target.value))} /></div></Field></div> : <Field label="Diesel" hint="R$ / litro"><div className="input-prefix"><span>R$</span><input type="number" min="0" step="0.01" value={fuelPrice} onChange={(e) => setFuelPrice(Number(e.target.value))} /></div></Field>}
          <Field label="Eficiência média" hint="km / litro · ajustável"><input title={efficiencyWasAdjusted ? "Eficiência alterada manualmente em relação ao padrão da classe." : "Eficiência padrão da classe selecionada."} type="number" min="0.1" step="0.1" value={efficiency} onChange={(e) => { const value = Number(e.target.value); setEfficiency(value); setEfficiencyWasAdjusted(Math.abs(value - (dieselEfficiencyByVehicle[vehicleRuleKey[vehicle]] ?? value)) > 0.001); }} /></Field>
          {efficiencyWasAdjusted && <div className="efficiency-alert" role="status">Eficiência ajustada manualmente. O consumo está sendo simulado com {number.format(efficiency)} km/l, diferente do padrão da classe.</div>}
        </div>
        <div className="form-section"><div className="section-heading"><Repeat size={17} /><span>Simulação mensal</span></div>
          <Field label="Viagens no mês" hint="repetições desta rota/cenário no período"><input type="number" min="0" value={monthlyTrips} onChange={(e) => setMonthlyTrips(Number(e.target.value))} /></Field>
          <div className="km-ruler"><div><span>Veículos / viagem</span><strong>{numberInt.format(calc.totalVehicles)}</strong></div><div className="ruler-line"><i style={{ width: `${Math.min(100, monthlyTrips > 0 ? 100 : 0)}%` }} /></div><div><span>Atendimentos no mês</span><strong className="amber-text">{numberInt.format(calc.monthlyVehicleServices)}</strong></div></div>
        </div>
      </aside>

      <section className="results-area">
        <div className="results-heading"><div><span className="section-kicker">02 / PROJEÇÃO</span><h2>Impacto financeiro da mudança</h2></div><div className="vehicle-badge"><Truck size={16} /> {vehicle} <span>•</span> {calc.projectedTotalKm} km projetados</div></div>
        <div className="hero-metric"><div><span className="metric-label">CUSTO PROJETADO / VEÍCULO</span><strong>{money.format(calc.projectedPerVehicle)}</strong><p>Diária {money.format(calc.fixedDaily)} + excedente {money.format(calc.projectedExcess)} ({projectedExcessKm} km × {money.format(excessRate)}) · diesel separado {money.format(calc.projectedFuelCost)}</p></div><div className="hero-side"><span>Nova regra total</span><b>{calc.projectedTotalKm} km</b><small>{projectedFranchise} km tabela + {projectedExcessKm} km excedentes</small></div></div>
        <div className="metrics-grid"><Metric label="Custo atual" value={money.format(calc.currentPerVehicle)} detail={`${currentFranchise} km de franquia`} icon={CircleDollarSign} /><Metric label="Variação / veículo" value={money.format(Math.abs(calc.savings))} detail={calc.savings >= 0 ? "redução projetada" : "acréscimo projetado"} tone={calc.savings >= 0 ? "positive" : "warning"} icon={calc.savings >= 0 ? ArrowDownRight : ArrowUpRight} /><Metric label="Combustível" value={money.format(calc.projectedFuelCost)} detail={`${number.format(calc.projectedTotalKm / Math.max(efficiency, 0.1))} litros estimados`} icon={Fuel} /><Metric label="Tempo de deslocamento" value={`${number.format(hours)} h`} detail={`${number.format(km / Math.max(hours, 0.1))} km/h médios`} icon={Clock3} /></div>

        <div className="consolidated-card monthly-projection-card"><div className="card-heading"><div><span className="section-kicker"><CalendarRange size={12} style={{ display: "inline", marginRight: 4, verticalAlign: -2 }} /> PROJEÇÃO MENSAL</span><h3>Impacto financeiro projetado para o mês</h3></div><span className="formula-note">{numberInt.format(monthlyTrips)} viagem(ns) × {numberInt.format(calc.totalVehicles)} veículo(s)/viagem</span></div><div className="metrics-grid metrics-grid-3"><Metric label="Custo de diária" value={money.format(calc.monthlyDailyCost)} detail={`${money.format(calc.projectedPerVehicle)} × ${numberInt.format(calc.totalVehicles)} veíc. × ${numberInt.format(monthlyTrips)} viagens`} icon={CircleDollarSign} /><Metric label="Custo de combustível" value={money.format(calc.monthlyFuelCost)} detail={`${money.format(calc.projectedFuelCost)} × ${numberInt.format(calc.totalVehicles)} veíc. × ${numberInt.format(monthlyTrips)} viagens`} icon={Fuel} /><Metric label="Clientes atendidos" value={numberInt.format(calc.monthlyClientsServed)} detail={`${numberInt.format(clients.length)} cliente(s) × ${numberInt.format(monthlyTrips)} viagens`} tone="positive" icon={UsersRound} /></div><div className="source-line">Custo mensal total (diária + combustível): <strong>{money.format(calc.monthlyTotalCost)}</strong> · estimativa rápida com 1 rota/km fixo — veja a projeção mensal por cliente na seção 03, mais abaixo.</div></div>

        <div className="scenario-toolbar"><div className="scenario-save"><input aria-label="Nome do cenário" placeholder="Nome do cenário" value={scenarioName} onChange={(e) => setScenarioName(e.target.value)} /><button type="button" className="secondary-action" onClick={saveScenario}><Save size={14} /> Salvar cenário</button></div><div className="scenario-load"><FolderOpen size={14} /><select aria-label="Carregar cenário" value="" onChange={(e) => { const scenario = savedScenarios.find((item) => item.id === e.target.value); if (scenario) loadScenario(scenario); }}><option value="">{scenariosLoaded ? "Carregar cenário salvo" : "Carregando cenários…"}</option>{savedScenarios.map((scenario) => <option key={scenario.id} value={scenario.id}>{scenario.name} · {scenario.savedAt}</option>)}</select></div><button type="button" className="import-button pdf-button" onClick={exportPdf}><FileDown size={14} /> Exportar PDF</button></div>

        <div className="rules-card"><div className="card-heading"><div><span className="section-kicker">BASE VIGENTE / PLANILHA</span><h3>Regra vigente por veículo</h3></div><div className="rules-actions"><span className="source-badge"><Database size={13} /> {sourceMeta.rowCount} registros</span><input ref={fileInputRef} className="hidden-file-input" type="file" accept=".xlsx,.xls" onChange={handleExcelImport} /><button className="import-button" type="button" onClick={() => fileInputRef.current?.click()}><Upload size={14} /> Importar Excel</button></div></div><div className="rule-selector"><div><label className="field-label" htmlFor="rule-select">Tabela e descrição</label><select id="rule-select" value={selectedRule?.table ?? ""} onChange={(event) => { const table = Number(event.target.value); setSelectedRuleTable(table); const rule = activeRules.find((item) => item.table === table); if (rule) { setDaily(rule.maxDaily); setCurrentFranchise(rule.exemptKm); setExcessRate(rule.kmRate); setHelperDaily(rule.resource); } }}>{activeRules.map((rule) => <option key={`${rule.table}-${rule.description}`} value={rule.table}>{rule.operation} · Tabela {rule.table} · {rule.description}</option>)}</select></div><button className="load-rule-button" type="button" onClick={() => selectedRule && loadRule(selectedRule)}>Usar na simulação</button></div>{selectedRule && <><div className="rule-metrics"><div><span>Diária máxima</span><strong>{money.format(selectedRule.maxDaily)}</strong><small>mín. {money.format(selectedRule.minDaily)}</small></div><div><span>Qtd. máxima/dia</span><strong>{number.format(selectedRule.maxDailyQty)}</strong><small>serviços possíveis</small></div><div><span>Valor do km</span><strong>{money.format(selectedRule.kmRate)}</strong><small>aplicado ao excedente</small></div><div><span>Saída excedente</span><strong>{selectedRule.excessDaily.toLocaleString("pt-BR")} · {money.format(selectedRule.maxDaily * selectedRule.excessDaily)}</strong><small>fator × diária máxima</small></div></div><div className="rule-detail-line"><span><b>{selectedRule.operation}</b> · Tabela {selectedRule.table} · {selectedRule.description} · rota {selectedRule.route}</span><span>Recurso: {money.format(selectedRule.resource)} · IDR: {selectedRule.idrPercent}%</span></div>{selectedRule.note && <div className="rule-note"><Info size={14} /> {selectedRule.note}</div>}{importError && <div className="import-error"><Info size={14} /> {importError}</div>}<div className="source-line">Fonte: {sourceMeta.name} · atualização {sourceMeta.importedAt}</div></>}</div>

        <div className="consolidated-card"><div className="card-heading"><div><span className="section-kicker">VISÃO CONSOLIDADA / TABELA</span><h3>Resumo por operação e classe de veículo</h3></div><span className="formula-note">seleção ligada ao simulador · combustível separado</span></div><div className="operation-filters"><span className="field-label">TIPO OPERAÇÃO</span>{operations.map((operation) => <button key={operation} type="button" className={operationFilter === operation ? "active" : ""} onClick={() => setOperationFilter(operation)}>{operation}</button>)}</div><div className="cost-chart"><div className="chart-heading"><div><span className="section-kicker">COMPARATIVO VISUAL</span><h4><BarChart3 size={16} /> Custo total por veículo</h4></div><small>menor regra simulada × {calc.totalVehicles} veículo(s)</small></div><div className="bar-chart">{chartRows.map((row) => <div className="bar-item" key={row.label}><div className="bar-label"><span>{row.label}</span><strong>{money.format(row.total)}</strong></div><div className="bar-track"><i style={{ width: `${Math.max(4, (row.total / chartMax) * 100)}%` }} /></div></div>)}</div></div><div className="rule-comparison-chart"><div className="chart-heading"><div><span className="section-kicker">IMPACTO DA MUDANÇA</span><h4><BarChart3 size={16} /> Regra Atual × Nova Regra</h4></div><small>frete por veículo · diária + KM excedente</small></div><div className="comparison-controls"><div><span className="field-label">CENÁRIO</span><select value={comparisonScenarioId} onChange={(e) => setComparisonScenarioId(e.target.value)}><option value="">Simulação atual</option>{savedScenarios.map((scenario) => <option key={scenario.id} value={scenario.id}>{scenario.name}</option>)}</select></div><div><span className="field-label">ORDENAR POR</span><select value={comparisonSort} onChange={(e) => setComparisonSort(e.target.value)}><option value="economia">Maior economia</option><option value="acrescimo">Maior acréscimo percentual</option></select></div><div><span className="field-label">VEÍCULOS NO GRÁFICO</span><div className="vehicle-checks">{vehicleOptions.map((label) => <label key={label}><input type="checkbox" checked={comparisonVehicles.includes(label)} onChange={(e) => setComparisonVehicles((current) => e.target.checked ? [...current, label] : current.filter((item) => item !== label))} /> {label}</label>)}</div></div></div><div className="multi-comparison-chart">{sortedMultiVehicleComparison.filter((row) => comparisonVehicles.includes(row.label)).map((row) => <div className="multi-comparison-row" key={row.label}><div className="multi-comparison-title"><strong>{row.label}</strong><span>Δ {money.format(row.difference)} · {row.percent.toLocaleString("pt-BR", { maximumFractionDigits: 1 })}%</span></div><div className="multi-bars"><div className="multi-bar-line"><small>Atual</small><div className="bar-track"><i className="current-bar" style={{ width: `${Math.max(3, (row.current / multiChartMax) * 100)}%` }} /></div><b>{money.format(row.current)}</b></div><div className="multi-bar-line"><small>Nova</small><div className="bar-track"><i className="projected-bar" style={{ width: `${Math.max(3, (row.projected / multiChartMax) * 100)}%` }} /></div><b>{money.format(row.projected)}</b></div></div></div>)}</div><div className="comparison-chart-foot"><span>{currentFranchise} km na regra atual</span><span>{projectedFranchise} km + {projectedExcessKm} km na nova regra</span></div></div><div className="consolidated-table"><div className="consolidated-head"><span>Tipo operação</span><span>Classe veículo</span><span>Valor km</span><span>Qtd. máxima diária</span><span>Saída excedente</span><span>Diária máxima</span><span>Valor recurso</span><span>Frete simulado</span></div>{consolidatedRows.map(({ rule }) => <div className={`consolidated-row ${rule.vehicle === vehicleRuleKey[vehicle] ? "current-vehicle" : ""}`} key={`${rule.operation}-${rule.vehicle}-${rule.table}-${rule.route}`}><span>{rule.operation}<small>Tabela {rule.table}</small></span><strong>{rule.vehicle}</strong><span>{money.format(rule.kmRate)}</span><span>{number.format(rule.maxDailyQty)}</span><span>{rule.excessDaily.toLocaleString("pt-BR")} · {money.format(rule.maxDaily * rule.excessDaily)}</span><span>{money.format(rule.maxDaily)}</span><span>{money.format(rule.resource)}</span><strong>{money.format(rule.maxDaily + Math.max(0, km - rule.exemptKm) * rule.kmRate)}</strong></div>)}</div></div>

        <div className="comparison-card"><div className="card-heading"><div><span className="section-kicker">LEITURA RÁPIDA / FRANQUIA</span><h3>Regra atual × cenário projetado</h3></div><span className="formula-note">frete: diária + km excedente informado</span></div><div className="comparison-columns"><div className="route-strip" aria-hidden="true"><span /><span /><span /><span /><span /><span /></div><div className="comparison-col"><div className="comparison-title"><span className="dot dot-muted" /> Regra atual</div><strong>{money.format(calc.currentPerVehicle)}</strong><div className="comparison-detail"><span>{currentFranchise} km vigentes</span><span>{number.format(calc.currentExcessKm)} km excedentes</span></div></div><div className="comparison-arrow">→</div><div className="comparison-col highlighted"><div className="comparison-title"><span className="dot dot-amber" /> Nova regra</div><strong>{money.format(calc.projectedPerVehicle)}</strong><div className="comparison-detail"><span>{projectedFranchise} km vigentes</span><span>{number.format(projectedExcessKm)} km × {money.format(excessRate)}</span></div></div></div></div>

        <div className="clients-card"><div className="card-heading"><div><span className="section-kicker">03 / OPERAÇÃO · MENSAL</span><h3>Clientes e projeção mensal</h3></div><div className="rules-actions"><input ref={monthlyFileInputRef} className="hidden-file-input" type="file" accept=".xlsx,.xls" onChange={handleMonthlyReportImport} /><button className="import-button" type="button" onClick={() => monthlyFileInputRef.current?.click()}><UploadCloud size={14} /> Importar relatório de coletas</button><button className="add-button" type="button" onClick={addClient}><Plus size={16} /> Adicionar cliente</button></div></div>
        {monthlyImportError && <div className="import-error"><Info size={14} /> {monthlyImportError}</div>}
        {monthlyReportMeta && <div className="source-line">Relatório importado: {monthlyReportMeta.name} · {monthlyReportMeta.clientCount} cliente(s) reconhecidos de {monthlyReportMeta.rowCount} linha(s) · {monthlyReportMeta.importedAt}</div>}
        <div className="client-table monthly-table"><div className="table-head"><span>Cliente / rota</span><span>Km totais</span><span>Veículos</span><span>Viagens/mês</span><span>Custo/viagem</span><span>Custo mensal</span><span /></div>{clientMonthlyRows.map((client) => <div className="table-row" key={client.id}><div className="client-name"><MapPin size={15} /><input value={client.name} onChange={(e) => updateClient(client.id, "name", e.target.value)} /></div><input type="number" min="0" value={client.km} onChange={(e) => updateClient(client.id, "km", e.target.value)} /><input type="number" min="1" value={client.vehicles} onChange={(e) => updateClient(client.id, "vehicles", e.target.value)} /><input type="number" min="0" value={client.monthlyTrips ?? 0} onChange={(e) => updateClient(client.id, "monthlyTrips", e.target.value)} /><strong>{money.format(client.perTripTotal)}</strong><strong className="amber-text">{money.format(client.monthlyTotal)}</strong><button className="icon-button" aria-label="Remover cliente" type="button" onClick={() => removeClient(client.id)}><Trash2 size={15} /></button></div>)}<div className="table-row monthly-totals-row"><div className="client-name"><strong>Total · {numberInt.format(clients.length)} cliente(s)</strong></div><span /><span /><strong>{numberInt.format(clientMonthlyTotals.trips)}</strong><span /><strong className="amber-text">{money.format(clientMonthlyTotals.total)}</strong><span /></div></div>
        </div>
        <div className="footnote"><Gauge size={15} /> <span>Racional por viagem: {money.format(calc.fixedDaily)} + {projectedExcessKm} km × {money.format(excessRate)} = {money.format(calc.projectedPerVehicle)} de frete + diesel simulado para {calc.projectedTotalKm} km. Mensal: diária {money.format(clientMonthlyTotals.freight)} + combustível {money.format(clientMonthlyTotals.fuel)} = {money.format(clientMonthlyTotals.total)}, considerando as viagens/mês informadas por cliente.</span></div>
      </section>
    </main>
  );
}

/* =============================================================================================
   PÁGINA 2 — ANÁLISE POR CLIENTE
   ============================================================================================= */
function ClientAnalysis({ manifestDataset, manifestSourceLabel }) {
  const [viewMode, setViewMode] = useState("daily");
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [selectedMonth, setSelectedMonth] = useState("all");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [dataset, setDataset] = useState({ cnpjs: collectionsCnpjs, names: collectionsNames, vehicleList: collectionsVehicleList, statusList: collectionsStatusList, records: collectionsRecords, validCollections: collectionsMeta.validCollections, rowCount: collectionsMeta.rowsAnalyzed, periodStart: collectionsMeta.periodStart, periodEnd: collectionsMeta.periodEnd });
  const [sourceLabel, setSourceLabel] = useState(collectionsMeta.sourceLabel);
  const [selectedDate, setSelectedDate] = useState(collectionsMeta.periodEnd);
  const [selectedDayVehicle, setSelectedDayVehicle] = useState(null);
  const [revenueDataset, setRevenueDataset] = useState({ cnpjs: revenueCnpjs, names: revenueNames, filiais: revenueFiliais, records: revenueRecords, year: revenueMeta.year });
  const [revenueSourceLabel, setRevenueSourceLabel] = useState(revenueMeta.sourceLabel);
  const [revenueImportError, setRevenueImportError] = useState(null);
  const [revenueYearInput, setRevenueYearInput] = useState(revenueMeta.year);
  const [revenueDate, setRevenueDate] = useState(collectionsMeta.periodEnd);
  const [revenueVehicleFilter, setRevenueVehicleFilter] = useState("ALL");
  const [revenueSplitView, setRevenueSplitView] = useState(false);
  const [revenueFilialFilter, setRevenueFilialFilter] = useState("GERAL");
  const [manifestVehicleEvents, setManifestVehicleEvents] = useState({ events: manifestVehicleEventsDefault, coverage: manifestCoverageDefault });
  const [revenueClientSearch, setRevenueClientSearch] = useState("");
  const [revenueClientSelected, setRevenueClientSelected] = useState(() => new Set());
  const revenueFileInputRef = useRef(null);
  const [importError, setImportError] = useState(null);
  const fileInputRef = useRef(null);

  const statusOptions = useMemo(() => dataset.statusList.filter((s) => dataset.records.some((r) => dataset.statusList[r[3]] === s)), [dataset]);
  const statusFilteredRecords = useMemo(() => statusFilter === "ALL" ? dataset.records : dataset.records.filter((r) => dataset.statusList[r[3]] === statusFilter), [dataset, statusFilter]);
  const statusScopeOffset = useMemo(() => {
    if (viewMode === "revenue") return isoToDayOffset(revenueDate);
    if (viewMode === "daily") return isoToDayOffset(selectedDate);
    return null;
  }, [viewMode, revenueDate, selectedDate]);
  const statusCounts = useMemo(() => {
    const map = new Map();
    dataset.records.forEach((r) => {
      if (statusScopeOffset !== null && r[2] !== statusScopeOffset) return;
      const s = dataset.statusList[r[3]];
      map.set(s, (map.get(s) ?? 0) + r[4]);
    });
    return map;
  }, [dataset, statusScopeOffset]);
  const statusScopeTotal = useMemo(() => {
    if (statusScopeOffset === null) return dataset.validCollections;
    return dataset.records.filter((r) => r[2] === statusScopeOffset).reduce((sum, r) => sum + r[4], 0);
  }, [dataset, statusScopeOffset]);

  /* ---------- Visão diária ---------- */
  const startOffset = isoToDayOffset(dataset.periodStart);
  const endOffset = isoToDayOffset(dataset.periodEnd);
  const dailyTotalsMap = useMemo(() => { const map = new Map(); statusFilteredRecords.forEach((r) => map.set(r[2], (map.get(r[2]) ?? 0) + r[4])); return map; }, [statusFilteredRecords]);
  const dayStrip = useMemo(() => { const days = []; const from = Math.max(startOffset, endOffset - 29); for (let o = from; o <= endOffset; o++) days.push({ offset: o, iso: dayOffsetToISO(o), count: dailyTotalsMap.get(o) ?? 0 }); return days; }, [dailyTotalsMap, startOffset, endOffset]);
  const dayStripMax = Math.max(...dayStrip.map((d) => d.count), 1);
  const selectedOffset = isoToDayOffset(selectedDate);
  const dayRecordsAll = useMemo(() => statusFilteredRecords.filter((r) => r[2] === selectedOffset), [statusFilteredRecords, selectedOffset]);
  const dayByVehicle = useMemo(() => { const map = new Map(); dayRecordsAll.forEach((r) => { const v = dataset.vehicleList[r[1]]; map.set(v, (map.get(v) ?? 0) + r[4]); }); return Array.from(map.entries()).sort((a, b) => b[1] - a[1]); }, [dayRecordsAll, dataset]);
  const dayRecords = useMemo(() => selectedDayVehicle ? dayRecordsAll.filter((r) => dataset.vehicleList[r[1]] === selectedDayVehicle) : dayRecordsAll, [dayRecordsAll, selectedDayVehicle, dataset]);
  const dayTotal = dayRecords.reduce((sum, r) => sum + r[4], 0);
  const dayClientRows = useMemo(() => dayRecords.map((r) => ({ cnpj: dataset.cnpjs[r[0]], name: dataset.names[r[0]], vehicle: dataset.vehicleList[r[1]], status: dataset.statusList[r[3]], count: r[4], nr: r[5] ?? [] })).filter((item) => `${item.cnpj} ${item.name}`.toLowerCase().includes(search.toLowerCase())).sort((a, b) => b.count - a.count), [dayRecords, dataset, search]);
  function shiftDay(delta) { const next = selectedOffset + delta; if (next >= startOffset && next <= endOffset) { setSelectedDate(dayOffsetToISO(next)); setSelectedDayVehicle(null); } }
  function selectDate(iso) { setSelectedDate(iso); setSelectedDayVehicle(null); }
  function formatNrList(nr) { if (!nr || !nr.length) return "—"; if (nr.length <= 3) return nr.join(", "); return `${nr[0]}–${nr[nr.length - 1]} (${nr.length}x)`; }

  /* ---------- Consolidado mensal ---------- */
  const monthOptions = useMemo(() => Array.from(new Set(statusFilteredRecords.map((r) => dayOffsetToISO(r[2]).slice(0, 7)))).sort(), [statusFilteredRecords]);
  const monthFilteredRecords = useMemo(() => selectedMonth === "all" ? statusFilteredRecords : statusFilteredRecords.filter((r) => dayOffsetToISO(r[2]).slice(0, 7) === selectedMonth), [statusFilteredRecords, selectedMonth]);
  const categoryTotals = useMemo(() => COLLECTION_CATEGORIES.map((cat) => {
    const matches = monthFilteredRecords.filter((r) => cat.match(dataset.vehicleList[r[1]]));
    return { ...cat, collections: matches.reduce((sum, r) => sum + r[4], 0), clients: new Set(matches.map((r) => r[0])).size };
  }), [monthFilteredRecords, dataset]);
  const monthlyRows = useMemo(() => {
    const grouped = new Map();
    monthFilteredRecords.forEach((r) => { const key = `${r[0]}|${r[1]}`; const current = grouped.get(key); const nrs = r[5] ?? []; grouped.set(key, current ? { collections: current.collections + r[4], nr: current.nr.concat(nrs) } : { collections: r[4], nr: nrs.slice() }); });
    return Array.from(grouped.entries()).map(([key, value]) => { const [cnpjIdxStr, vCodeStr] = key.split("|"); const cnpjIdx = Number(cnpjIdxStr); const vehicle = dataset.vehicleList[Number(vCodeStr)]; const nrSorted = value.nr.slice().sort((a, b) => a - b); return { cnpj: dataset.cnpjs[cnpjIdx], name: dataset.names[cnpjIdx], vehicle, collections: value.collections, nr: nrSorted }; });
  }, [monthFilteredRecords, dataset]);
  const activeCategory = COLLECTION_CATEGORIES.find((cat) => cat.key === selectedCategory);
  const monthlyFiltered = useMemo(() => monthlyRows.filter((item) => {
    const matchesCategory = !activeCategory || activeCategory.match(item.vehicle);
    const haystack = `${item.cnpj} ${item.name}`.toLowerCase();
    return matchesCategory && haystack.includes(search.toLowerCase());
  }).sort((a, b) => b.collections - a.collections || a.name.localeCompare(b.name)), [monthlyRows, activeCategory, search]);
  const totalCollections = monthlyFiltered.reduce((sum, item) => sum + item.collections, 0);
  const totalDaily = monthlyFiltered.reduce((sum, item) => sum + item.collections * (dailyByVehicle[item.vehicle] ?? 0), 0);
  const uniqueClients = new Set(monthlyFiltered.map((item) => item.cnpj)).size;

  /* ---------- Faturamento (projeção diária a partir da planilha de Receita) ---------- */
  const revenueCnpjIndexByCnpj = useMemo(() => new Map(revenueDataset.cnpjs.map((c, i) => [c, i])), [revenueDataset]);
  const manifestCountsByDay = useMemo(() => {
    const map = new Map();
    manifestVehicleEvents.events.forEach(([offset, groupIdx, classIdx]) => {
      const group = MANIFEST_VEHICLE_GROUPS[groupIdx];
      const cls = MANIFEST_CLASSES[classIdx];
      if (!map.has(offset)) map.set(offset, { CARRETA: { DEDICADO: 0, ROTA: 0 }, CAMINHAO: { DEDICADO: 0, ROTA: 0 } });
      map.get(offset)[group][cls] += 1;
    });
    return map;
  }, [manifestVehicleEvents]);
  const revenueFixedCnpjIndex = useMemo(() => new Map(revenueFixedCnpjs.map((c, i) => [c, i])), []);
  const revenueByKeyGeral = useMemo(() => {
    const map = new Map();
    revenueDataset.records.forEach((r) => {
      const key = `${r[0]}|${r[1]}`;
      const current = map.get(key) ?? { receita: 0, qtdCte: 0, volume: 0, pesoReal: 0, pesoCalculo: 0 };
      current.receita += r[3]; current.qtdCte += r[4]; current.volume += r[5]; current.pesoReal += r[6]; current.pesoCalculo += r[7];
      map.set(key, current);
    });
    return map;
  }, [revenueDataset]);
  const revenueByKeyFilial = useMemo(() => new Map(revenueDataset.records.map((r) => [`${r[0]}|${r[1]}|${r[2]}`, { receita: r[3], qtdCte: r[4], volume: r[5], pesoReal: r[6], pesoCalculo: r[7] }])), [revenueDataset]);
  const revenueClientMatches = useMemo(() => { const q = revenueClientSearch.trim().toLowerCase(); if (!q) return []; return dataset.cnpjs.map((cnpj, idx) => ({ cnpj, name: dataset.names[idx] })).filter((c) => `${c.cnpj} ${c.name}`.toLowerCase().includes(q)).slice(0, 8); }, [dataset, revenueClientSearch]);
  function toggleRevenueClient(cnpj) { setRevenueClientSelected((current) => { const next = new Set(current); if (next.has(cnpj)) next.delete(cnpj); else next.add(cnpj); return next; }); }
  function computeRevenueDay(dayOffset, forceGroup) {
    const iso = dayOffsetToISO(dayOffset);
    const [y, mo] = iso.split("-").map(Number);
    const businessDays = businessDaysInMonth(y, mo);
    const filialIdx = revenueFilialFilter === "GERAL" ? null : revenueDataset.filiais.indexOf(revenueFilialFilter);
    const activeFilter = forceGroup ?? revenueVehicleFilter;
    let totalFaturamento = 0, totalVolume = 0, totalPeso = 0, countCarreta = 0, countCaminhao = 0;
    const clientMap = new Map();
    statusFilteredRecords.forEach((r) => {
      if (r[2] !== dayOffset) return;
      const cnpj = dataset.cnpjs[r[0]];
      if (revenueClientSelected.size && !revenueClientSelected.has(cnpj)) return;
      const vehicle = dataset.vehicleList[r[1]];
      const group = vehicleRevenueGroup(vehicle);
      if (activeFilter !== "ALL" && activeFilter !== group) return;
      const count = r[4];
      if (group === "CARRETA") countCarreta += count; else countCaminhao += count;
      let valorMedio = null, fonte = "sem_dados";
      const fixedIdx = revenueFixedCnpjIndex.get(cnpj);
      if (fixedIdx !== undefined) {
        valorMedio = revenueFixedValores[fixedIdx];
        fonte = "fixo";
      } else {
        const revIdx = revenueCnpjIndexByCnpj.get(cnpj);
        const rev = revIdx === undefined ? null : filialIdx === null ? revenueByKeyGeral.get(`${revIdx}|${mo}`) : revenueByKeyFilial.get(`${revIdx}|${mo}|${filialIdx}`);
        if (rev) {
          valorMedio = businessDays > 0 ? rev.receita / businessDays : 0;
          fonte = "mensal";
          const avgVol = rev.qtdCte > 0 ? rev.volume / rev.qtdCte : 0;
          const avgPeso = rev.qtdCte > 0 ? rev.pesoCalculo / rev.qtdCte : 0;
          totalVolume += avgVol * count;
          totalPeso += avgPeso * count;
        }
      }
      const valorGrupo = valorMedio === null ? 0 : valorMedio * REVENUE_GROUP_FACTOR[group];
      const valorPrevisto = valorGrupo * count;
      totalFaturamento += valorPrevisto;
      const key = `${cnpj}|${group}`;
      const current = clientMap.get(key) ?? { cnpj, name: dataset.names[r[0]], group, qtd: 0, valorMedio: valorGrupo, valorPrevisto: 0, fonte };
      current.qtd += count;
      current.valorPrevisto += valorPrevisto;
      clientMap.set(key, current);
    });
    const clientRows = Array.from(clientMap.values()).sort((a, b) => b.valorPrevisto - a.valorPrevisto);
    /* Contagem de veículos: por manifesto (1 manifesto = 1 veículo) quando há cobertura de manifesto para
       o dia e nenhum filtro de cliente está ativo; senão, cai no fallback por ordem de coleta (acima). */
    const manifestDay = !revenueClientSelected.size ? manifestCountsByDay.get(dayOffset) : undefined;
    let vehicleCountSource = "ordem", dedicadoCarreta = null, rotaCarreta = null, dedicadoCaminhao = null, rotaCaminhao = null;
    let finalCountCarreta = countCarreta, finalCountCaminhao = countCaminhao;
    if (manifestDay) {
      vehicleCountSource = "manifesto";
      if (activeFilter === "ALL" || activeFilter === "CARRETA") { dedicadoCarreta = manifestDay.CARRETA.DEDICADO; rotaCarreta = manifestDay.CARRETA.ROTA; }
      if (activeFilter === "ALL" || activeFilter === "CAMINHAO") { dedicadoCaminhao = manifestDay.CAMINHAO.DEDICADO; rotaCaminhao = manifestDay.CAMINHAO.ROTA; }
      finalCountCarreta = (dedicadoCarreta ?? 0) + (rotaCarreta ?? 0);
      finalCountCaminhao = (dedicadoCaminhao ?? 0) + (rotaCaminhao ?? 0);
    }
    return { iso, totalFaturamento, totalVolume, totalPeso, countCarreta: finalCountCarreta, countCaminhao: finalCountCaminhao, totalVeiculos: finalCountCarreta + finalCountCaminhao, clientRows, vehicleCountSource, dedicadoCarreta, rotaCarreta, dedicadoCaminhao, rotaCaminhao };
  }
  const selectedRevenueOffset = isoToDayOffset(revenueDate);
  const revenueDeps = [statusFilteredRecords, dataset, revenueVehicleFilter, revenueFilialFilter, revenueClientSelected, revenueByKeyGeral, revenueByKeyFilial, revenueCnpjIndexByCnpj, manifestCountsByDay];
  const currentDayRevenue = useMemo(() => computeRevenueDay(selectedRevenueOffset), [selectedRevenueOffset, ...revenueDeps]);
  const previousDayRevenue = useMemo(() => computeRevenueDay(selectedRevenueOffset - 1), [selectedRevenueOffset, ...revenueDeps]);
  const currentDayCarreta = useMemo(() => computeRevenueDay(selectedRevenueOffset, "CARRETA"), [selectedRevenueOffset, ...revenueDeps]);
  const previousDayCarreta = useMemo(() => computeRevenueDay(selectedRevenueOffset - 1, "CARRETA"), [selectedRevenueOffset, ...revenueDeps]);
  const currentDayCaminhao = useMemo(() => computeRevenueDay(selectedRevenueOffset, "CAMINHAO"), [selectedRevenueOffset, ...revenueDeps]);
  const previousDayCaminhao = useMemo(() => computeRevenueDay(selectedRevenueOffset - 1, "CAMINHAO"), [selectedRevenueOffset, ...revenueDeps]);
  /* ---------- Tendência Carreta x Caminhão (linhas separadas) ---------- */
  const vehicleTrendSplit = useMemo(() => {
    const from = Math.max(startOffset, selectedRevenueOffset - 13);
    const days = [];
    for (let o = from; o <= selectedRevenueOffset; o++) {
      days.push({ iso: dayOffsetToISO(o), carreta: computeRevenueDay(o, "CARRETA"), caminhao: computeRevenueDay(o, "CAMINHAO") });
    }
    return days;
  }, [startOffset, selectedRevenueOffset, ...revenueDeps]);
  const vehicleTrendMax = Math.max(...vehicleTrendSplit.map((d) => Math.max(d.carreta.totalFaturamento, d.caminhao.totalFaturamento)), 1);

  /* ---------- Mix Carreta x Caminhão no dia (rosca) ---------- */
  const vehicleMixToday = useMemo(() => {
    const total = currentDayRevenue.countCarreta + currentDayRevenue.countCaminhao;
    const pctCarreta = total > 0 ? (currentDayRevenue.countCarreta / total) * 100 : 0;
    const pctCaminhao = total > 0 ? 100 - pctCarreta : 0;
    return { total, pctCarreta, pctCaminhao, countCarreta: currentDayRevenue.countCarreta, countCaminhao: currentDayRevenue.countCaminhao };
  }, [currentDayRevenue]);

  /* ---------- Distribuição de status por dia (barra empilhada) ---------- */
  const statusTrend = useMemo(() => {
    const from = Math.max(startOffset, selectedRevenueOffset - 13);
    const days = [];
    for (let o = from; o <= selectedRevenueOffset; o++) {
      let total = 0;
      const byStatus = new Map();
      dataset.records.forEach((r) => {
        if (r[2] !== o) return;
        const cnpj = dataset.cnpjs[r[0]];
        if (revenueClientSelected.size && !revenueClientSelected.has(cnpj)) return;
        const vehicle = dataset.vehicleList[r[1]];
        const group = vehicleRevenueGroup(vehicle);
        if (revenueVehicleFilter !== "ALL" && revenueVehicleFilter !== group) return;
        const status = dataset.statusList[r[3]];
        byStatus.set(status, (byStatus.get(status) ?? 0) + r[4]);
        total += r[4];
      });
      days.push({ offset: o, iso: dayOffsetToISO(o), total, segments: Array.from(byStatus.entries()).map(([status, count]) => ({ status, count, pct: total > 0 ? (count / total) * 100 : 0 })).sort((a, b) => b.count - a.count) });
    }
    return days;
  }, [startOffset, selectedRevenueOffset, dataset, revenueVehicleFilter, revenueClientSelected]);
  const statusesInTrend = useMemo(() => Array.from(new Set(statusTrend.flatMap((d) => d.segments.map((s) => s.status)))), [statusTrend]);

  /* ---------- Padrão semanal do mês (semana 1/2/3/4 + dia de pico) ---------- */
  const weeklyPattern = useMemo(() => {
    const [y, mo] = revenueDate.split("-").map(Number);
    const daysInMonth = new Date(y, mo, 0).getDate();
    const monthStartOffset = isoToDayOffset(`${y}-${String(mo).padStart(2, "0")}-01`);
    const dayTotals = new Map();
    dataset.records.forEach((r) => {
      const offset = r[2];
      if (offset < monthStartOffset || offset >= monthStartOffset + daysInMonth) return;
      const cnpj = dataset.cnpjs[r[0]];
      if (revenueClientSelected.size && !revenueClientSelected.has(cnpj)) return;
      const vehicle = dataset.vehicleList[r[1]];
      const group = vehicleRevenueGroup(vehicle);
      if (revenueVehicleFilter !== "ALL" && revenueVehicleFilter !== group) return;
      dayTotals.set(offset, (dayTotals.get(offset) ?? 0) + r[4]);
    });
    const weeks = [];
    for (let w = 0; w * 7 < daysInMonth; w++) {
      const startDay = w * 7 + 1;
      const endDay = Math.min(daysInMonth, startDay + 6);
      let total = 0, peakOffset = null, peakCount = -1;
      for (let d = startDay; d <= endDay; d++) {
        const offset = monthStartOffset + d - 1;
        const count = dayTotals.get(offset) ?? 0;
        total += count;
        if (count > peakCount) { peakCount = count; peakOffset = offset; }
      }
      weeks.push({ label: `Semana ${w + 1}`, startDay, endDay, total, peakOffset, peakCount: Math.max(0, peakCount) });
    }
    const monthTotal = weeks.reduce((sum, w) => sum + w.total, 0);
    const overallPeak = weeks.reduce((best, w) => (w.peakCount > (best?.peakCount ?? -1) ? w : best), null);
    return { weeks, monthTotal, monthLabel: `${REVENUE_MONTH_LABELS[mo]}/${y}`, overallPeak, weekMax: Math.max(...weeks.map((w) => w.total), 1) };
  }, [revenueDate, dataset, revenueVehicleFilter, revenueClientSelected]);
  function pctChange(curr, prev) { if (!prev) return null; return ((curr - prev) / prev) * 100; }
  const faturamentoPct = pctChange(currentDayRevenue.totalFaturamento, previousDayRevenue.totalFaturamento);
  const volumePct = pctChange(currentDayRevenue.totalVolume, previousDayRevenue.totalVolume);
  const pesoPct = pctChange(currentDayRevenue.totalPeso, previousDayRevenue.totalPeso);
  const veiculosPct = pctChange(currentDayRevenue.totalVeiculos, previousDayRevenue.totalVeiculos);
  function formatPct(pct) { return pct === null ? "—" : `${pct > 0 ? "+" : ""}${number.format(pct)}%`; }
  function shiftRevenueDay(delta) { const next = selectedRevenueOffset + delta; if (next >= startOffset && next <= endOffset) setRevenueDate(dayOffsetToISO(next)); }
  const revenueYearMatches = Number(revenueDate.slice(0, 4)) === revenueDataset.year;

  async function handleRevenueImport(event) {
    const file = event.target.files?.[0];
    if (!file) return;
    setRevenueImportError(null);
    try {
      const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" });
      const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { header: 1, defval: "" });
      const imported = parseRevenueReport(rows, revenueYearInput || revenueDataset.year, dataset.cnpjs);
      setRevenueDataset({ cnpjs: imported.cnpjs, names: imported.names, filiais: imported.filiais, records: imported.records, year: imported.year });
      setRevenueFilialFilter("GERAL");
      setRevenueSourceLabel(`${file.name} · ${numberInt.format(imported.rowCount)} linhas · ano ${imported.year} · ${imported.cnpjs.length} CNPJ(s) do relatório de coletas`);
    } catch (error) { setRevenueImportError(error instanceof Error ? error.message : "Não foi possível ler a planilha de receita."); }
    finally { event.target.value = ""; }
  }


  async function handleClientImport(event) {
    const file = event.target.files?.[0];
    if (!file) return;
    setImportError(null);
    try {
      const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" });
      const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { defval: "" });
      const imported = parseCollectionsReport(rows, manifestDataset?.byManifest);
      setDataset({ cnpjs: imported.cnpjs, names: imported.names, vehicleList: imported.vehicleList, statusList: imported.statusList, records: imported.records, validCollections: imported.validCollections, rowCount: imported.rowCount, periodStart: imported.periodStart, periodEnd: imported.periodEnd });
      setSourceLabel(`${file.name} · base em DT_EFETUAR_COLETAS${manifestDataset ? ` · ${numberInt.format(imported.dedupCount)} coleta(s) deduplicada(s) via manifesto` : ""}`);
      setSelectedCategory(null);
      setSelectedMonth("all");
      setStatusFilter("ALL");
      setSelectedDate(imported.periodEnd);
      setSelectedDayVehicle(null);
      setRevenueDate(imported.periodEnd);
      setManifestVehicleEvents(imported.manifestCoverage ? { events: imported.manifestEvents, coverage: imported.manifestCoverage } : { events: [], coverage: null });
    } catch (error) { setImportError(error instanceof Error ? error.message : "Não foi possível ler a base de coletas."); }
    finally { event.target.value = ""; }
  }


  return <main className="client-page">
    <div className="client-page-heading"><div><span className="section-kicker">04 / DEMANDA POR CLIENTE</span><h2>Coletas consolidadas por CNPJ</h2><p>Coletas no período de {formatDatePtBR(dataset.periodStart)} a {formatDatePtBR(dataset.periodEnd)}, com base em DT_EFETUAR_COLETAS e DS_STATUS_COLETAS.</p></div><div className="client-source"><Database size={15} /> {sourceLabel}<small>{numberInt.format(dataset.rowCount)} linhas · {numberInt.format(dataset.validCollections)} coletas no total</small></div></div>

    <div className="view-tabs"><button type="button" className={viewMode === "daily" ? "active" : ""} onClick={() => setViewMode("daily")}><Clock3 size={14} /> Visão diária</button><button type="button" className={viewMode === "monthly" ? "active" : ""} onClick={() => setViewMode("monthly")}><BarChart3 size={14} /> Consolidado mensal</button><button type="button" className={viewMode === "revenue" ? "active" : ""} onClick={() => setViewMode("revenue")}><CircleDollarSign size={14} /> Faturamento</button></div>

    <div className="status-tiles-wrap">
      {statusScopeOffset !== null && <div className="status-scope-hint"><CalendarRange size={12} /> Quantitativo do dia {formatDatePtBR(dayOffsetToISO(statusScopeOffset))} — muda conforme a data selecionada {viewMode === "revenue" ? "no Faturamento" : "na Visão diária"}</div>}
      <div className="status-tiles"><button type="button" className={`status-chip tone-neutral ${statusFilter === "ALL" ? "active" : ""}`} onClick={() => setStatusFilter("ALL")}>Todos<small>{numberInt.format(statusScopeTotal)}</small></button>{statusOptions.map((status) => <button key={status} type="button" className={`status-chip tone-${STATUS_TONE[status] ?? "neutral"} ${statusFilter === status ? "active" : ""}`} onClick={() => setStatusFilter(status)}>{statusLabel(status)}<small>{numberInt.format(statusCounts.get(status) ?? 0)}</small></button>)}</div>
    </div>

    {viewMode === "daily" ? <>
      <div className="day-strip-card"><div className="card-heading"><div><span className="section-kicker">LINHA DO TEMPO</span><h3>Coletas por dia · últimos {dayStrip.length} dias</h3></div><div className="day-nav"><button type="button" onClick={() => shiftDay(-1)} disabled={selectedOffset <= startOffset}>◀ Dia anterior</button><input type="date" min={dataset.periodStart} max={dataset.periodEnd} value={selectedDate} onChange={(e) => selectDate(e.target.value)} /><button type="button" onClick={() => shiftDay(1)} disabled={selectedOffset >= endOffset}>Próximo dia ▶</button></div></div><div className="day-strip">{dayStrip.map((d) => <button key={d.offset} type="button" className={`day-bar ${d.iso === selectedDate ? "active" : ""}`} onClick={() => selectDate(d.iso)} title={`${formatDatePtBR(d.iso)} · ${d.count} coleta(s)`}><span className="day-bar-track"><i style={{ height: `${Math.max(4, (d.count / dayStripMax) * 100)}%` }} /></span><small>{d.iso.slice(8, 10)}</small></button>)}</div></div>

      <div className="day-detail-card"><div className="card-heading"><div><span className="section-kicker">{weekdayLabel(selectedDate).toUpperCase()}</span><h3>{formatDatePtBR(selectedDate)} — {numberInt.format(dayTotal)} coleta(s)</h3></div><span className="formula-note">filtro de status: {statusFilter === "ALL" ? "Todos" : statusLabel(statusFilter)}</span></div>
        <div className="day-vehicle-breakdown">{dayByVehicle.length === 0 && <span className="empty-note">Nenhuma coleta neste dia para o filtro atual.</span>}{dayByVehicle.map(([vehicle, count]) => <button type="button" key={vehicle} className={`day-vehicle-chip ${selectedDayVehicle === vehicle ? "active" : ""}`} onClick={() => setSelectedDayVehicle((current) => current === vehicle ? null : vehicle)}><Truck size={13} /> {vehicleLabels[vehicle] ?? vehicle}<strong>{numberInt.format(count)}</strong></button>)}{selectedDayVehicle && <button type="button" className="day-vehicle-chip clear-chip" onClick={() => setSelectedDayVehicle(null)}>Limpar filtro</button>}</div>
        <div className="client-toolbar"><div className="client-search"><Search size={16} /><input aria-label="Pesquisar cliente ou CNPJ" placeholder="Pesquisar CNPJ ou nome do cliente" value={search} onChange={(event) => setSearch(event.target.value)} /></div></div>
        <div className="client-grid-head day-grid-head"><span>Cliente / CNPJ</span><span>Veículo</span><span>Status</span><span>Coletas</span><span>Nº coleta (NR_COLETAS)</span></div>
        {dayClientRows.map((item, idx) => <div className="client-grid-row day-grid-row" key={`${item.cnpj}-${item.vehicle}-${item.status}-${idx}`}><div><strong>{item.name}</strong><small>{item.cnpj}</small></div><span className="vehicle-tag"><Truck size={13} /> {vehicleLabels[item.vehicle] ?? item.vehicle}</span><span className={`status-pill tone-${STATUS_TONE[item.status] ?? "neutral"}`}>{statusLabel(item.status)}</span><strong className="collection-count">{numberInt.format(item.count)}x</strong><small className="nr-coletas">{formatNrList(item.nr)}</small></div>)}
        {dayClientRows.length === 0 && <div className="empty-client-state"><RouteIcon size={18} /> Nenhuma coleta encontrada para os filtros atuais neste dia.</div>}
      </div>
    </> : viewMode === "monthly" ? <>
      <div className="client-summary-grid"><div className="client-summary-card"><span>Clientes únicos</span><strong>{numberInt.format(uniqueClients)}</strong><small>CNPJ na seleção atual</small></div><div className="client-summary-card highlight"><span>Coletas classificadas</span><strong>{numberInt.format(totalCollections)}</strong><small>{selectedMonth === "all" ? "período completo" : monthLabel(selectedMonth)}</small></div><div className="client-summary-card"><span>Diária projetada</span><strong>{money.format(totalDaily)}</strong><small>referência por coleta</small></div><div className="client-summary-card"><span>Perfil selecionado</span><strong>{activeCategory ? activeCategory.label : "Todos"}</strong><small>toque num card abaixo para filtrar</small></div></div>

      <div className="category-tiles">{categoryTotals.map((cat) => <button key={cat.key} type="button" className={`category-tile ${selectedCategory === cat.key ? "active" : ""} ${cat.collections === 0 ? "empty" : ""}`} onClick={() => setSelectedCategory((current) => current === cat.key ? null : cat.key)}><Truck size={18} /><strong>{cat.label}</strong><span>{numberInt.format(cat.collections)} coleta(s)</span><small>{numberInt.format(cat.clients)} cliente(s)</small></button>)}</div>

      <section className="client-table-card"><div className="client-toolbar"><div className="client-search"><Search size={16} /><input aria-label="Pesquisar cliente ou CNPJ" placeholder="Pesquisar CNPJ ou nome do cliente" value={search} onChange={(event) => setSearch(event.target.value)} /></div><div className="client-filters"><select className="month-select" value={selectedMonth} onChange={(e) => setSelectedMonth(e.target.value)}><option value="all">Período completo</option>{monthOptions.map((m) => <option key={m} value={m}>{monthLabel(m)}</option>)}</select>{activeCategory && <button type="button" onClick={() => setSelectedCategory(null)}>Limpar filtro · {activeCategory.label}</button>}</div></div><div className="client-grid-head monthly-grid-head"><span>Cliente / CNPJ</span><span>Tipo de veículo</span><span>Coletas</span><span>Nº coleta (NR_COLETAS)</span><span>Diária de referência</span><span>Projeção do grupo</span></div>{monthlyFiltered.map((item) => <div className="client-grid-row monthly-grid-row" key={`${item.cnpj}-${item.vehicle}`}><div><strong>{item.name}</strong><small>{item.cnpj}</small></div><span className="vehicle-tag"><Truck size={13} /> {vehicleLabels[item.vehicle] ?? item.vehicle}</span><strong className="collection-count">{numberInt.format(item.collections)}x</strong><small className="nr-coletas">{formatNrList(item.nr)}</small><span>{money.format(dailyByVehicle[item.vehicle] ?? 0)}</span><strong>{money.format(item.collections * (dailyByVehicle[item.vehicle] ?? 0))}</strong></div>)}{monthlyFiltered.length === 0 && <div className="empty-client-state"><RouteIcon size={18} /> Nenhum cliente encontrado para os filtros atuais.</div>}</section>
      <div className="client-footnote"><span>Regra de consolidação:</span> agrupa por CNPJ_CLIENTES_SOL + Classe do Veículo dentro do filtro de status e mês escolhidos. Projeção do grupo = diária de referência do veículo × quantidade de coletas. Ex.: {monthlyFiltered[0] ? `${monthlyFiltered[0].name.split(" ")[0]} · ${vehicleLabels[monthlyFiltered[0].vehicle] ?? monthlyFiltered[0].vehicle} · ${monthlyFiltered[0].collections}x` : "cliente · veículo · Nx"}.</div>
    </> : <>
      <div className="day-strip-card revenue-toolbar-card"><div className="card-heading"><div><span className="section-kicker">PROJEÇÃO DE FATURAMENTO</span><h3>Comparativo diário · {formatDatePtBR(revenueDate)}</h3></div><div className="day-nav"><button type="button" onClick={() => shiftRevenueDay(-1)} disabled={selectedRevenueOffset <= startOffset}>◀ Dia anterior</button><input type="date" value={revenueDate} onChange={(e) => setRevenueDate(e.target.value)} /><button type="button" onClick={() => shiftRevenueDay(1)} disabled={selectedRevenueOffset >= endOffset}>Próximo dia ▶</button></div></div>
        <div className="revenue-view-toggle"><button type="button" className={!revenueSplitView ? "active" : ""} onClick={() => setRevenueSplitView(false)}><BarChart3 size={13} /> Visão unificada</button><button type="button" className={revenueSplitView ? "active" : ""} onClick={() => setRevenueSplitView(true)}><Truck size={13} /> Dividir Carreta / Caminhão</button></div>
        <div className="revenue-filters">
          <div className={`revenue-filter-group ${revenueSplitView ? "revenue-filter-disabled" : ""}`}><span className="field-label">CATEGORIA DE VEÍCULO {revenueSplitView && "(ignorado na visão dividida)"}</span><div className="revenue-chip-row"><button type="button" disabled={revenueSplitView} className={revenueVehicleFilter === "ALL" ? "active" : ""} onClick={() => setRevenueVehicleFilter("ALL")}>Todos</button><button type="button" disabled={revenueSplitView} className={revenueVehicleFilter === "CARRETA" ? "active" : ""} onClick={() => setRevenueVehicleFilter("CARRETA")}>Carreta</button><button type="button" disabled={revenueSplitView} className={revenueVehicleFilter === "CAMINHAO" ? "active" : ""} onClick={() => setRevenueVehicleFilter("CAMINHAO")}>Caminhão</button></div></div>
          <div className="revenue-filter-group"><span className="field-label">GRUPO DE CLIENTES</span><div className="client-search"><Search size={14} /><input aria-label="Buscar cliente para filtrar" placeholder="Buscar cliente ou CNPJ para incluir no filtro" value={revenueClientSearch} onChange={(e) => setRevenueClientSearch(e.target.value)} /></div>{(revenueClientMatches.length > 0 || revenueClientSelected.size > 0) && <div className="revenue-chip-row">{revenueClientMatches.map((c) => <button type="button" key={c.cnpj} className={revenueClientSelected.has(c.cnpj) ? "active" : ""} onClick={() => toggleRevenueClient(c.cnpj)}>{c.name.split(" ").slice(0, 2).join(" ")}</button>)}{revenueClientSelected.size > 0 && <button type="button" className="clear-chip" onClick={() => setRevenueClientSelected(new Set())}>Limpar seleção ({revenueClientSelected.size})</button>}</div>}</div>
          <div className="revenue-filter-group"><span className="field-label">FILIAL DE ORIGEM</span><select className="month-select" value={revenueFilialFilter} onChange={(e) => setRevenueFilialFilter(e.target.value)}><option value="GERAL">Geral (todas as filiais)</option>{revenueDataset.filiais.map((f) => <option key={f} value={f}>{filialSigla(f)} — {f}</option>)}</select></div>
        </div>
      </div>

      {!revenueYearMatches && <div className="import-error revenue-year-warning"><Info size={14} /> O fallback mensal (clientes sem valor fixo calibrado) usa a planilha de {revenueDataset.year}; o dia selecionado ({formatDatePtBR(revenueDate)}) está fora desse ano, então esses clientes específicos podem ficar zerados. Os clientes com valor fixo calibrado não são afetados.</div>}

      {revenueSplitView ? (
      <div className="revenue-split-grid">
        {[
          { key: "CARRETA", label: "Carreta", curr: currentDayCarreta, prev: previousDayCarreta },
          { key: "CAMINHAO", label: "Caminhão", curr: currentDayCaminhao, prev: previousDayCaminhao },
        ].map(({ key, label, curr, prev }) => {
          const splitPct = pctChange(curr.totalFaturamento, prev.totalFaturamento);
          const splitPctVeic = pctChange(curr.totalVeiculos, prev.totalVeiculos);
          return <div className="revenue-split-panel" key={key}>
            <div className="revenue-split-header"><Truck size={16} /><h3>{label}</h3><span className="revenue-split-count">{numberInt.format(curr.totalVeiculos)} veículo(s) no dia {curr.vehicleCountSource === "manifesto" ? "· via manifesto" : "· por ordem (sem manifesto)"}</span></div>
            <div className="revenue-split-metrics">
              <div><span>Faturamento previsto</span><strong>{money.format(curr.totalFaturamento)}</strong><small className={splitPct === null ? "" : splitPct < 0 ? "tone-warning" : "tone-positive"}>{formatPct(splitPct)}</small></div>
              <div><span>Veículos no dia</span><strong>{numberInt.format(curr.totalVeiculos)}</strong><small className={splitPctVeic === null ? "" : splitPctVeic < 0 ? "tone-warning" : "tone-positive"}>{formatPct(splitPctVeic)}</small></div>
              <div><span>Volumetria prevista</span><strong>{number.format(curr.totalVolume)}</strong></div>
              <div><span>Peso previsto (kg)</span><strong>{numberInt.format(curr.totalPeso)}</strong></div>
            </div>
            {curr.vehicleCountSource === "manifesto" && <div className="revenue-split-dedicado-rota">
              <div className="dedicado-rota-item"><span>Dedicado</span><strong>{numberInt.format((key === "CARRETA" ? curr.dedicadoCarreta : curr.dedicadoCaminhao) ?? 0)}</strong><small>1–2 clientes no manifesto</small></div>
              <div className="dedicado-rota-item"><span>Rota</span><strong>{numberInt.format((key === "CARRETA" ? curr.rotaCarreta : curr.rotaCaminhao) ?? 0)}</strong><small>3+ clientes no manifesto</small></div>
            </div>}
            <div className="revenue-split-clients">
              <div className="revenue-client-grid-head revenue-split-grid-cols"><span>Cliente / CNPJ</span><span>Qtd</span><span>Valor Médio</span><span>Valor Previsto</span><span>Fonte</span></div>
              {curr.clientRows.map((c) => <div className="revenue-client-grid-row revenue-split-grid-cols" key={c.cnpj}><div><strong>{c.name}</strong><small>{c.cnpj}</small></div><strong>{numberInt.format(c.qtd)}</strong><span>{money.format(c.valorMedio)}</span><strong>{money.format(c.valorPrevisto)}</strong><span className={`revenue-source-tag revenue-source-${c.fonte}`}>{c.fonte === "fixo" ? "Fixo" : c.fonte === "mensal" ? "Mensal" : "Sem dados"}</span></div>)}
              {curr.clientRows.length === 0 && <div className="empty-client-state"><RouteIcon size={16} /> Nenhuma coleta de {label.toLowerCase()} neste dia.</div>}
            </div>
          </div>;
        })}
      </div>
      ) : <>
      <div className="revenue-comparison-grid">
        <div className="revenue-compare-card"><div className="revenue-compare-title">Faturamento</div><table className="revenue-compare-table"><thead><tr><th>Data</th><th>Faturamento</th></tr></thead><tbody><tr><td>{formatDatePtBR(previousDayRevenue.iso)}</td><td>{money.format(previousDayRevenue.totalFaturamento)}</td></tr><tr><td>{formatDatePtBR(currentDayRevenue.iso)}</td><td>{money.format(currentDayRevenue.totalFaturamento)}</td></tr></tbody></table><div className={`revenue-compare-pct ${faturamentoPct === null ? "" : faturamentoPct < 0 ? "tone-warning" : "tone-positive"}`}>{formatPct(faturamentoPct)}</div></div>

        <div className="revenue-compare-card"><div className="revenue-compare-title">Volumetria Prevista</div><table className="revenue-compare-table"><thead><tr><th>Data</th><th>Volumetria</th></tr></thead><tbody><tr><td>{formatDatePtBR(previousDayRevenue.iso)}</td><td>{number.format(previousDayRevenue.totalVolume)}</td></tr><tr><td>{formatDatePtBR(currentDayRevenue.iso)}</td><td>{number.format(currentDayRevenue.totalVolume)}</td></tr></tbody></table><div className={`revenue-compare-pct ${volumePct === null ? "" : volumePct < 0 ? "tone-warning" : "tone-positive"}`}>{formatPct(volumePct)}</div></div>

        <div className="revenue-compare-card"><div className="revenue-compare-title">Peso Previsto</div><table className="revenue-compare-table"><thead><tr><th>Data</th><th>Peso (kg)</th></tr></thead><tbody><tr><td>{formatDatePtBR(previousDayRevenue.iso)}</td><td>{numberInt.format(previousDayRevenue.totalPeso)}</td></tr><tr><td>{formatDatePtBR(currentDayRevenue.iso)}</td><td>{numberInt.format(currentDayRevenue.totalPeso)}</td></tr></tbody></table><div className={`revenue-compare-pct ${pesoPct === null ? "" : pesoPct < 0 ? "tone-warning" : "tone-positive"}`}>{formatPct(pesoPct)}</div></div>

        <div className="revenue-compare-card revenue-compare-wide"><div className="revenue-compare-title">Total de Evento x Veículo</div><table className="revenue-compare-table revenue-vehicle-table"><thead><tr><th>Data</th><th>Carreta</th><th>Caminhão</th><th>Total Veículo</th></tr></thead><tbody><tr><td>{formatDatePtBR(previousDayRevenue.iso)}</td><td>{numberInt.format(previousDayRevenue.countCarreta)}</td><td>{numberInt.format(previousDayRevenue.countCaminhao)}</td><td>{numberInt.format(previousDayRevenue.totalVeiculos)}</td></tr><tr><td>{formatDatePtBR(currentDayRevenue.iso)}</td><td>{numberInt.format(currentDayRevenue.countCarreta)}</td><td>{numberInt.format(currentDayRevenue.countCaminhao)}</td><td>{numberInt.format(currentDayRevenue.totalVeiculos)}</td></tr></tbody></table><div className={`revenue-compare-pct ${veiculosPct === null ? "" : veiculosPct < 0 ? "tone-warning" : "tone-positive"}`}>{formatPct(veiculosPct)}</div></div>
      </div>

      <div className={`revenue-summary-banner ${faturamentoPct === null ? "" : faturamentoPct < 0 ? "tone-warning" : "tone-positive"}`}>{faturamentoPct === null ? "Sem coletas no dia anterior para comparação." : `Previsão de ${faturamentoPct < 0 ? "redução" : "aumento"} de ${number.format(Math.abs(faturamentoPct))}% no faturamento em ${formatDatePtBR(currentDayRevenue.iso)} em relação a ${formatDatePtBR(previousDayRevenue.iso)}.`}</div>

      <div className="revenue-client-card"><div className="card-heading"><div><span className="section-kicker">CLIENTES PROJETADOS NO DIA</span><h3>{formatDatePtBR(currentDayRevenue.iso)} — {numberInt.format(currentDayRevenue.clientRows.length)} cliente(s)/veículo(s)</h3></div><span className="formula-note">Fixo = valor médio calibrado (Mar–Mai/2025) · Mensal = fallback dinâmico · Sem dados = sem receita associada</span></div>
        <div className="revenue-client-grid-head"><span>Cliente / CNPJ</span><span>Categoria</span><span>Qtd</span><span>Valor Médio</span><span>Valor Previsto</span><span>Fonte</span></div>
        {currentDayRevenue.clientRows.map((c) => <div className="revenue-client-grid-row" key={`${c.cnpj}-${c.group}`}><div><strong>{c.name}</strong><small>{c.cnpj}</small></div><span className="vehicle-tag"><Truck size={13} /> {REVENUE_GROUP_LABELS[c.group]}</span><strong>{numberInt.format(c.qtd)}</strong><span>{money.format(c.valorMedio)}</span><strong>{money.format(c.valorPrevisto)}</strong><span className={`revenue-source-tag revenue-source-${c.fonte}`}>{c.fonte === "fixo" ? "Fixo" : c.fonte === "mensal" ? "Mensal" : "Sem dados"}</span></div>)}
        {currentDayRevenue.clientRows.length === 0 && <div className="empty-client-state"><RouteIcon size={18} /> Nenhuma coleta encontrada para os filtros atuais neste dia.</div>}
      </div>
      </>}

            <div className="revenue-analytics-grid">
        <div className="status-trend-card">
          <div className="card-heading"><div><span className="section-kicker">STATUS DAS COLETAS</span><h3>Distribuição por dia · últimos {statusTrend.length} dias</h3></div></div>
          <div className="status-trend-legend">{statusesInTrend.map((s) => <span key={s} className={`status-legend-item tone-${STATUS_TONE[s] ?? "neutral"}`}><i /> {statusLabel(s)}</span>)}</div>
          <div className="status-trend-rows">{statusTrend.map((d) => <div className="status-trend-row" key={d.iso}><span className="status-trend-date">{d.iso.slice(8, 10)}/{d.iso.slice(5, 7)}</span><div className="status-trend-bar">{d.total === 0 ? <div className="status-trend-segment tone-neutral" style={{ width: "100%", opacity: .25 }} /> : d.segments.map((seg) => <div key={seg.status} className={`status-trend-segment tone-${STATUS_TONE[seg.status] ?? "neutral"}`} style={{ width: `${seg.pct}%` }} title={`${statusLabel(seg.status)}: ${numberInt.format(seg.count)} (${number.format(seg.pct)}%)`}>{seg.pct >= 14 && <span>{number.format(seg.pct)}%</span>}</div>)}</div><span className="status-trend-total">{numberInt.format(d.total)}</span></div>)}</div>
        </div>

        <div className="vehicle-mix-card">
          <div className="card-heading"><div><span className="section-kicker">MIX DE VEÍCULOS</span><h3>Carreta × Caminhão · {formatDatePtBR(currentDayRevenue.iso)}</h3></div></div>
          <div className="vehicle-mix-body">
            <div className="vehicle-mix-donut" style={{ background: vehicleMixToday.total > 0 ? `conic-gradient(var(--amber) 0% ${vehicleMixToday.pctCarreta}%, var(--green) ${vehicleMixToday.pctCarreta}% 100%)` : "var(--border)" }}><div className="vehicle-mix-donut-hole"><strong>{numberInt.format(vehicleMixToday.total)}</strong><span>veículo(s)</span></div></div>
            <div className="vehicle-mix-legend">
              <div className="vehicle-mix-legend-item"><i className="dot-carreta" />Carreta<strong>{numberInt.format(vehicleMixToday.countCarreta)}</strong><span>{number.format(vehicleMixToday.pctCarreta)}%</span></div>
              <div className="vehicle-mix-legend-item"><i className="dot-caminhao" />Caminhão<strong>{numberInt.format(vehicleMixToday.countCaminhao)}</strong><span>{number.format(vehicleMixToday.pctCaminhao)}%</span></div>
            </div>
          </div>
        </div>
      </div>

      <div className="weekly-pattern-card">
        <div className="card-heading"><div><span className="section-kicker">PADRÃO SEMANAL</span><h3>Disponibilização de carga por semana · {weeklyPattern.monthLabel}</h3></div></div>
        <div className="weekly-pattern-bars">{weeklyPattern.weeks.map((w) => { const pct = weeklyPattern.monthTotal > 0 ? (w.total / weeklyPattern.monthTotal) * 100 : 0; const barPct = (w.total / weeklyPattern.weekMax) * 100; const isPeak = weeklyPattern.overallPeak && w.label === weeklyPattern.overallPeak.label; return <div className={`weekly-pattern-col ${isPeak ? "is-peak" : ""}`} key={w.label}><div className="weekly-pattern-bar-track"><div className="weekly-pattern-bar-fill" style={{ height: `${Math.max(3, barPct)}%` }} /></div><strong>{numberInt.format(w.total)}</strong><span>{number.format(pct)}%</span><small>{w.label}<br />dias {w.startDay}–{w.endDay}</small>{w.peakCount > 0 && <em>Pico {dayOffsetToISO(w.peakOffset).slice(8, 10)}/{dayOffsetToISO(w.peakOffset).slice(5, 7)} · {numberInt.format(w.peakCount)}</em>}</div>; })}</div>
        <div className="client-footnote"><span>Leitura:</span> cada barra é uma semana do mês (dias 1–7, 8–14, 15–21, 22–28, 29+). O % é a fatia da carga do mês concentrada naquela semana; "Pico" é o dia de maior volume dentro dela — mostra quando a carga fica mais concentrada. Semana em destaque = maior pico do mês.</div>
      </div>

      <div className="revenue-trend-card">
        <div className="card-heading"><div><span className="section-kicker">TENDÊNCIA</span><h3>Faturamento previsto · Carreta × Caminhão · últimos {vehicleTrendSplit.length} dias</h3></div></div>
        <div className="vehicle-trend-legend"><span className="trend-legend-item"><i style={{ background: "var(--amber)" }} />Carreta</span><span className="trend-legend-item"><i style={{ background: "var(--green)" }} />Caminhão</span></div>
        <svg className="vehicle-trend-svg" viewBox={`0 0 ${Math.max(1, vehicleTrendSplit.length - 1) * 56 + 48} 190`} preserveAspectRatio="none">
          <polyline fill="none" stroke="var(--amber)" strokeWidth="2.5" points={vehicleTrendSplit.map((d, i) => `${i * 56 + 24},${170 - (d.carreta.totalFaturamento / vehicleTrendMax) * 155}`).join(" ")} />
          <polyline fill="none" stroke="var(--green)" strokeWidth="2.5" points={vehicleTrendSplit.map((d, i) => `${i * 56 + 24},${170 - (d.caminhao.totalFaturamento / vehicleTrendMax) * 155}`).join(" ")} />
          {vehicleTrendSplit.map((d, i) => <circle key={`c-${d.iso}`} cx={i * 56 + 24} cy={170 - (d.carreta.totalFaturamento / vehicleTrendMax) * 155} r="3.2" fill="var(--amber)" />)}
          {vehicleTrendSplit.map((d, i) => <circle key={`m-${d.iso}`} cx={i * 56 + 24} cy={170 - (d.caminhao.totalFaturamento / vehicleTrendMax) * 155} r="3.2" fill="var(--green)" />)}
        </svg>
        <div className="vehicle-trend-axis">{vehicleTrendSplit.map((d) => <span key={d.iso}>{d.iso.slice(8, 10)}/{d.iso.slice(5, 7)}</span>)}</div>
      </div>

      <div className="client-toolbar import-toolbar revenue-import-toolbar"><input ref={revenueFileInputRef} className="hidden-file-input" type="file" accept=".xlsx,.xls" onChange={handleRevenueImport} /><button className="secondary-action" type="button" onClick={() => revenueFileInputRef.current?.click()}><UploadCloud size={15} /> Atualizar planilha de Receita</button><label className="revenue-year-field">Ano<input type="number" className="revenue-year-input" value={revenueYearInput} onChange={(e) => setRevenueYearInput(Number(e.target.value) || revenueDataset.year)} /></label><span className="source-badge"><Database size={13} /> {revenueSourceLabel}</span>{revenueImportError && <div className="import-error">{revenueImportError}</div>}</div>

      <div className="client-footnote"><span>Metodologia (atualizada):</span> cada cliente tem um Valor Médio calibrado com a mesma conta já usada na planilha real (abas Auxiliar/Faturamento Original): soma da Receita de Março+Abril+Maio/2025 ÷ 4 ÷ 22 dias úteis — esse valor é FIXO por cliente, não muda de mês pra mês. Carreta (Cav. Mecânico, incluindo variações como conjunto completo/especial/bitrem) recebe 100% desse valor por veículo despachado no dia; Toco/Truck/Van/Fiorino/Outros (Caminhão) recebem 50%. Isso cobre 81 dos 140 CNPJs do relatório de coletas — marcados como "Fixo" na tabela de clientes acima. Para os demais, o painel cai num fallback "Mensal" (Receita do mês ÷ dias úteis, planilha nacional por filial) só pra não zerar a projeção; e quando nem isso existe, aparece "Sem dados". Volumetria e peso previstos (só no fallback mensal) usam a média por CT-e do cliente no mês. <span>Deduplicação por manifesto:</span> quando o relatório de manifesto está carregado, aplicamos 2 regras — (1) GRUPO: no mesmo NR_DIARIO_BORDO (=NR_MANIFESTOS), CNPJs que são o mesmo grupo comercial (NM_CLIENTES_GRUPO do relatório de coletas, ex.: ACHE + LABOFARMA) viram 1 serviço só, mesmo em cidades diferentes; (2) LOCAL: no que sobrar, mesmo manifesto + mesma cidade + exatamente 2 CNPJs distintos também vira 1 serviço. Em ambas, mantém o CNPJ de maior Valor Médio. <span>Contagem de veículos (Dividir Carreta/Caminhão):</span> passou a contar por manifesto (1 manifesto = 1 veículo no dia), não por ordem de coleta — um manifesto com várias ordens do mesmo grupo não conta como vários carros. Cada veículo é classificado como "Dedicado" (1–2 clientes distintos no manifesto) ou "Rota" (3+ clientes) — visível na visão dividida. Isso vale para todo o período com manifesto vinculado (hoje, 01/05 a 02/09/2026); fora dessa janela, a contagem cai no fallback por ordem de coleta, indicado no rótulo "veículo(s) no dia". <span>Categoria do veículo por manifesto:</span> quando o NR_DIARIO_BORDO bate com um manifesto, a categoria (Carreta/Caminhão) passa a ser validada pelo CLASSE_VEICULO_VIAGEM do manifesto — ligado à placa — em vez do campo da própria coleta, que pode ter digitação inconsistente; a ordem de coleta segue essa fonte. Fique de olho na coluna "Fonte" da tabela de clientes: ela mostra exatamente qual regra gerou cada valor.</div>
    </>}

    <div className="client-toolbar import-toolbar">
      <input ref={fileInputRef} className="hidden-file-input" type="file" accept=".xlsx,.xls" onChange={handleClientImport} />
      <button className="secondary-action" type="button" onClick={() => fileInputRef.current?.click()}><UploadCloud size={15} /> Atualizar base de coletas</button>
      <span className={`manifest-status-badge ${manifestDataset ? "manifest-status-on" : "manifest-status-off"}`}><RouteIcon size={13} /> {manifestSourceLabel}<small className="manifest-status-hint">· atualize em Recursos - Veículos</small></span>
      {importError && <div className="import-error client-import-error">{importError}</div>}
    </div>
  </main>;
}

/* =============================================================================================
   APP
   ============================================================================================= */
/* =============================================================================================
   PÁGINA 3 — RECURSOS - VEÍCULOS (em construção)
   Por enquanto: importação do relatório de manifesto (NR_MANIFESTOS, IDENT_VEICULOS_TRACAO,
   PC_APROVEITAMENTO, CLASSE_VEICULO_VIAGEM) e um resumo inicial. O dataset carregado aqui também
   alimenta a deduplicação de coletas por veículo usada em Análise por Cliente › Faturamento.
   ============================================================================================= */
/* Bloco reutilizável "Placa x Dia" — mesma estrutura visual da Frequência por Placa (coletas),
   usado também para Entregas e Devoluções, sempre calculado ao vivo a partir do manifesto importado. */
function FrequencyPlateBlock({ title, subtitle, dataByPlate, search, onSearchChange, footnote, icon }) {
  const IconTag = icon || Truck;
  const filtered = useMemo(() => {
    let plates = Array.from(dataByPlate.keys());
    const q = search.trim().toUpperCase();
    if (q) plates = plates.filter((p) => p.includes(q));
    return plates.sort((a, b) => (dataByPlate.get(b)?.length ?? 0) - (dataByPlate.get(a)?.length ?? 0));
  }, [dataByPlate, search]);
  return <section className="client-table-card">
    <div className="client-toolbar"><div><strong>{title}</strong><small>{subtitle}</small></div></div>
    <div className="client-search"><Search size={14} /><input placeholder="Buscar placa" value={search} onChange={(e) => onSearchChange(e.target.value.toUpperCase())} /></div>
    <div className="frequency-plate-list">
      {filtered.slice(0, 40).map((placa) => {
        const days = dataByPlate.get(placa);
        return <div className="frequency-plate-block" key={placa}>
          <div className="frequency-plate-header"><IconTag size={14} /><strong>{placa}</strong><span>{numberInt.format(days.length)} dia(s) ativo(s) no período</span></div>
          <div className="frequency-days-row">{days.slice(0, 25).map((d) => <span className="frequency-day-chip" key={d.offset}>{dayOffsetToISO(d.offset).slice(8, 10)}/{dayOffsetToISO(d.offset).slice(5, 7)} · {numberInt.format(d.count)}x</span>)}{days.length > 25 && <span className="frequency-day-chip frequency-day-more">+{days.length - 25}</span>}</div>
        </div>;
      })}
      {filtered.length === 0 && <div className="empty-client-state"><IconTag size={16} /> Nenhuma placa encontrada — importe/atualize o relatório de manifesto acima para preencher esta tabela.</div>}
      {filtered.length > 40 && <div className="client-footnote">Mostrando as 40 placas mais ativas para os filtros atuais — refine a busca por placa para ver outras.</div>}
    </div>
    {footnote && <div className="client-footnote">{footnote}</div>}
  </section>;
}

function VehicleResources({ manifestDataset, manifestSourceLabel, manifestImportError, manifestFileInputRef, handleManifestImport }) {
  const [registry, setRegistry] = useState(() => vehicleRegistryDefault.map((r, i) => ({ ...r, id: i })));
  const [newEntry, setNewEntry] = useState({ placa: "", status: "PRÓPRIO", motorista: "", categoria: "CAV.MECANICO" });
  const [selectedCities, setSelectedCities] = useState(() => new Set());
  const [freqPlateSearch, setFreqPlateSearch] = useState("");
  const [entregasPlateSearch, setEntregasPlateSearch] = useState("");
  const [devolucoesPlateSearch, setDevolucoesPlateSearch] = useState("");

  function addRegistryEntry() {
    const placa = newEntry.placa.trim().toUpperCase();
    if (!placa) return;
    setRegistry((curr) => [...curr, { placa, status: newEntry.status, motorista: newEntry.motorista.trim(), categoria: newEntry.categoria, viagens: 0, id: `novo-${Date.now()}` }]);
    setNewEntry({ placa: "", status: "PRÓPRIO", motorista: "", categoria: "CAV.MECANICO" });
  }
  function removeRegistryEntry(id) { setRegistry((curr) => curr.filter((r) => r.id !== id)); }
  function toggleCity(cityIdx) { setSelectedCities((curr) => { const next = new Set(curr); if (next.has(cityIdx)) next.delete(cityIdx); else next.add(cityIdx); return next; }); }

  const frequencyByPlate = useMemo(() => {
    const map = new Map();
    vehicleFrequencyDefault.forEach(([plateIdx, offset, count, cityIdxs]) => {
      if (selectedCities.size && !cityIdxs.some((ci) => selectedCities.has(ci))) return;
      const placa = vehicleFrequencyPlates[plateIdx];
      if (!map.has(placa)) map.set(placa, []);
      map.get(placa).push({ offset, count, cities: cityIdxs.map((ci) => vehicleFrequencyCities[ci]) });
    });
    map.forEach((entries) => entries.sort((a, b) => b.offset - a.offset));
    return map;
  }, [selectedCities]);

  const frequencyPlatesFiltered = useMemo(() => {
    let plates = Array.from(frequencyByPlate.keys());
    const q = freqPlateSearch.trim().toUpperCase();
    if (q) plates = plates.filter((p) => p.includes(q));
    return plates.sort((a, b) => (frequencyByPlate.get(b)?.length ?? 0) - (frequencyByPlate.get(a)?.length ?? 0));
  }, [frequencyByPlate, freqPlateSearch]);

  /* Entregas e Devoluções por placa/dia — mesma lógica da Frequência por Placa (coletas), mas calculada
     ao vivo a partir de QT_ENTREGAS_VIAGENS e QTD_CTE_NAO_ENTREGUE do relatório de manifesto já importado
     acima. Fica pronta para preencher sozinha assim que houver manifesto com essas colunas. */
  const entregasByPlate = useMemo(() => {
    const byPlateDay = new Map();
    if (manifestDataset) for (const rec of manifestDataset.byManifest.values()) {
      if (!rec.placa || !rec.entregas) continue;
      const iso = parseCollectionDate(rec.data);
      if (!iso) continue;
      const offset = isoToDayOffset(iso);
      if (!byPlateDay.has(rec.placa)) byPlateDay.set(rec.placa, new Map());
      const dayMap = byPlateDay.get(rec.placa);
      dayMap.set(offset, (dayMap.get(offset) ?? 0) + rec.entregas);
    }
    const result = new Map();
    byPlateDay.forEach((dayMap, placa) => result.set(placa, Array.from(dayMap.entries()).map(([offset, count]) => ({ offset, count })).sort((a, b) => b.offset - a.offset)));
    return result;
  }, [manifestDataset]);

  const devolucoesByPlate = useMemo(() => {
    const byPlateDay = new Map();
    if (manifestDataset) for (const rec of manifestDataset.byManifest.values()) {
      if (!rec.placa || !rec.devolucoes) continue;
      const iso = parseCollectionDate(rec.data);
      if (!iso) continue;
      const offset = isoToDayOffset(iso);
      if (!byPlateDay.has(rec.placa)) byPlateDay.set(rec.placa, new Map());
      const dayMap = byPlateDay.get(rec.placa);
      dayMap.set(offset, (dayMap.get(offset) ?? 0) + rec.devolucoes);
    }
    const result = new Map();
    byPlateDay.forEach((dayMap, placa) => result.set(placa, Array.from(dayMap.entries()).map(([offset, count]) => ({ offset, count })).sort((a, b) => b.offset - a.offset)));
    return result;
  }, [manifestDataset]);

  const registryStatusClass = (s) => s === "PRÓPRIO" ? "registry-status-proprio" : s === "AGREGADO" ? "registry-status-agregado" : "registry-status-particular";

  return <main className="client-page">
    <div className="client-page-heading">
      <div>
        <span className="section-kicker">06 / RECURSOS - VEÍCULOS</span>
        <h2>Ocupação e recursos de veículos</h2>
        <p>Cadastro de veículos/motoristas e análise de frequência a partir do relatório de manifesto — também alimenta a deduplicação de coletas em Análise por Cliente › Faturamento.</p>
      </div>
      <div className="client-source"><RouteIcon size={15} /> {manifestSourceLabel}</div>
    </div>

    <div className="client-toolbar import-toolbar">
      <input ref={manifestFileInputRef} className="hidden-file-input" type="file" accept=".xlsx,.xls" onChange={handleManifestImport} />
      <button className="secondary-action" type="button" onClick={() => manifestFileInputRef.current?.click()}><UploadCloud size={15} /> Atualizar relatório de manifesto</button>
      {manifestImportError && <div className="import-error client-import-error">{manifestImportError}</div>}
    </div>

    {manifestDataset && <div className="client-summary-grid">
      <div className="client-summary-card highlight"><span>Manifestos carregados</span><strong>{numberInt.format(manifestDataset.totalManifests)}</strong><small>NR_MANIFESTOS únicos</small></div>
      <div className="client-summary-card"><span>Placas distintas</span><strong>{numberInt.format(manifestDataset.uniquePlates)}</strong><small>IDENT_VEICULOS_TRACAO</small></div>
      <div className="client-summary-card"><span>Aproveitamento médio</span><strong>{manifestDataset.avgAproveitamento !== null ? `${number.format(manifestDataset.avgAproveitamento * 100)}%` : "—"}</strong><small>PC_APROVEITAMENTO</small></div>
      <div className="client-summary-card"><span>Classes de veículo</span><strong>{numberInt.format(manifestDataset.classeBreakdown.length)}</strong><small>CLASSE_VEICULO_VIAGEM</small></div>
    </div>}

    <section className="client-table-card">
      <div className="client-toolbar"><div><strong>Registro de veículos e motoristas</strong><small>{numberInt.format(registry.length)} veículo(s) cadastrado(s) · inclua ou remova conforme a frota mudar</small></div></div>
      <div className="vehicle-registry-form">
        <input placeholder="Placa" value={newEntry.placa} onChange={(e) => setNewEntry((c) => ({ ...c, placa: e.target.value.toUpperCase() }))} />
        <select value={newEntry.status} onChange={(e) => setNewEntry((c) => ({ ...c, status: e.target.value }))}>
          <option value="PRÓPRIO">Próprio</option><option value="AGREGADO">Agregado</option><option value="PARTICULAR">Particular</option>
        </select>
        <input placeholder="Motorista / Proprietário" value={newEntry.motorista} onChange={(e) => setNewEntry((c) => ({ ...c, motorista: e.target.value }))} />
        <select value={newEntry.categoria} onChange={(e) => setNewEntry((c) => ({ ...c, categoria: e.target.value }))}>
          {["CAV.MECANICO", "TOCO", "TRUCK", "FIORINO", "VAN", "VUC", "TOCO 3/4"].map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
        <button type="button" className="add-button" onClick={addRegistryEntry}><Plus size={14} /> Incluir</button>
      </div>
      <div className="vehicle-registry-grid-head"><span>Status</span><span>Placa</span><span>Motorista / Proprietário</span><span>Categoria</span><span>Viagens</span><span /></div>
      {registry.map((r) => <div className="vehicle-registry-grid-row" key={r.id}>
        <span className={`registry-status-tag ${registryStatusClass(r.status)}`}>{r.status}</span>
        <strong>{r.placa}</strong>
        <span>{r.motorista || "—"}</span>
        <span>{r.categoria}</span>
        <span>{numberInt.format(r.viagens || 0)}</span>
        <button type="button" className="icon-button" onClick={() => removeRegistryEntry(r.id)} title="Remover"><Trash2 size={14} /></button>
      </div>)}
      {registry.length === 0 && <div className="empty-client-state"><Truck size={16} /> Nenhum veículo cadastrado. Use o formulário acima para incluir.</div>}
      <div className="client-footnote"><span>Fonte:</span> status (Próprio/Agregado/Particular), motorista e categoria vêm de TIPO_PROPRIETARIO_VEICULO_VIAGEM, NM_MOTORISTAS e CLASSE_VEICULO_VIAGEM do manifesto — usamos o valor mais frequente por placa no período. Não é literalmente "Frota/Afretado": os valores reais do relatório são Próprio/Agregado/Particular; ajuste os rótulos aqui se preferir outra nomenclatura.</div>
    </section>

    <section className="client-table-card">
      <div className="client-toolbar"><div><strong>Frequência por placa</strong><small>Quantos serviços cada veículo fez, por dia — filtre por cidade de atendimento</small></div></div>
      <div className="revenue-chip-row frequency-city-filter">
        {vehicleFrequencyCities.map((c, i) => <button key={c} type="button" className={selectedCities.has(i) ? "active" : ""} onClick={() => toggleCity(i)}>{c}</button>)}
        {selectedCities.size > 0 && <button type="button" className="clear-chip" onClick={() => setSelectedCities(new Set())}>Limpar filtro ({selectedCities.size})</button>}
      </div>
      <div className="client-search"><Search size={14} /><input placeholder="Buscar placa" value={freqPlateSearch} onChange={(e) => setFreqPlateSearch(e.target.value.toUpperCase())} /></div>
      <div className="frequency-plate-list">
        {frequencyPlatesFiltered.slice(0, 40).map((placa) => {
          const days = frequencyByPlate.get(placa);
          return <div className="frequency-plate-block" key={placa}>
            <div className="frequency-plate-header"><Truck size={14} /><strong>{placa}</strong><span>{numberInt.format(days.length)} dia(s) ativo(s) no período</span></div>
            <div className="frequency-days-row">{days.slice(0, 25).map((d) => <span className="frequency-day-chip" key={d.offset} title={d.cities.join(", ")}>{dayOffsetToISO(d.offset).slice(8, 10)}/{dayOffsetToISO(d.offset).slice(5, 7)} · {d.count}x</span>)}{days.length > 25 && <span className="frequency-day-chip frequency-day-more">+{days.length - 25}</span>}</div>
          </div>;
        })}
        {frequencyPlatesFiltered.length === 0 && <div className="empty-client-state"><Truck size={16} /> Nenhuma placa encontrada para os filtros atuais.</div>}
        {frequencyPlatesFiltered.length > 40 && <div className="client-footnote">Mostrando as 40 placas mais ativas para os filtros atuais — refine a busca por placa para ver outras.</div>}
      </div>
      <div className="client-footnote"><span>Leitura:</span> "2x" significa 2 manifestos distintos daquela placa naquele dia (2 saídas). A frequência é calculada a partir das coletas já deduplicadas por manifesto, então reflete o mesmo critério usado no Faturamento. <span>Próximo passo:</span> cruzar essa frequência com a diária + regra de saída adicional (ex.: 2ª saída = 40% do valor) do simulador de frete, para estimar o custo diário por veículo — e, mais adiante, o relatório de viagens para status de pagamento.</div>
    </section>

    <FrequencyPlateBlock
      title="Frequência de Entregas por placa"
      subtitle="Quantas entregas cada veículo fez, por dia — calculado a partir do manifesto importado"
      dataByPlate={entregasByPlate}
      search={entregasPlateSearch}
      onSearchChange={setEntregasPlateSearch}
      footnote={<><span>Fonte:</span> soma de QT_ENTREGAS_VIAGENS por IDENT_VEICULOS_TRACAO e DT_VIAGENS do relatório de manifesto.</>}
    />

    <FrequencyPlateBlock
      title="Frequência de Devoluções por placa"
      subtitle="Quantas devoluções/CTes não entregues cada veículo teve, por dia"
      dataByPlate={devolucoesByPlate}
      search={devolucoesPlateSearch}
      onSearchChange={setDevolucoesPlateSearch}
      footnote={<><span>Fonte:</span> soma de QTD_CTE_NAO_ENTREGUE por IDENT_VEICULOS_TRACAO e DT_VIAGENS do relatório de manifesto — ajuste esta coluna de origem se o critério de "devolução" do seu setor for outro (ex.: QTD_COLETA_RECUSADA, QT_IDR_VIAGENS).</>}
    />
  </main>;
}

export default function App() {
  const [page, setPage] = useState("home");
  const [theme, setTheme] = useState("dark");
  const [manifestDataset, setManifestDataset] = useState(null);
  const [manifestSourceLabel, setManifestSourceLabel] = useState("Nenhum relatório de manifesto carregado");
  const [manifestImportError, setManifestImportError] = useState(null);
  const manifestFileInputRef = useRef(null);

  useEffect(() => {
    const root = document.documentElement;
    if (theme === "dark") root.classList.add("dark"); else root.classList.remove("dark");
  }, [theme]);

  const toggleTheme = () => setTheme((prev) => (prev === "light" ? "dark" : "light"));

  async function handleManifestImport(event) {
    const file = event.target.files?.[0];
    if (!file) return;
    setManifestImportError(null);
    try {
      const workbook = XLSX.read(await file.arrayBuffer(), { type: "array" });
      const rows = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]], { header: 1, defval: "" });
      const parsed = parseManifestReport(rows);
      setManifestDataset(parsed);
      setManifestSourceLabel(`${file.name} · ${numberInt.format(parsed.totalManifests)} manifesto(s) · ${numberInt.format(parsed.uniquePlates)} placa(s)`);
    } catch (error) { setManifestImportError(error instanceof Error ? error.message : "Não foi possível ler a planilha de manifesto."); }
    finally { event.target.value = ""; }
  }

  return (
    <div className={`app-shell ${page === "clients" || page === "vehicles" ? "client-analysis-shell" : ""}`}>
      <style>{CSS_TEXT}</style>
      <DashboardLayout page={page} setPage={setPage} theme={theme} toggleTheme={toggleTheme} />
      <TopBar page={page} setPage={setPage} />
      {page === "home" ? <Home /> : page === "clients" ? <ClientAnalysis manifestDataset={manifestDataset} manifestSourceLabel={manifestSourceLabel} /> : <VehicleResources manifestDataset={manifestDataset} manifestSourceLabel={manifestSourceLabel} manifestImportError={manifestImportError} manifestFileInputRef={manifestFileInputRef} handleManifestImport={handleManifestImport} />}
    </div>
  );
}
